export const COMPONENT_REFERENCE: Record<string, string> = {
 "Accordion": "## Accordion — Collapsible sections from an items list; one or many open.\nTag: <Accordion> (group: navigation)\nProps (? = optional):\n- items: AccordionItem[] — Accordion items\n- multiple?: boolean — Allow multiple panels open\n- defaultOpenKeys?: string[] — Default open keys\n- openKeys?: string[] — Controlled open keys\n- variant?: \"default\" | \"bordered\" | \"separated\" — Accordion variant\n- headingLevel?: 2 | 3 | 4 | 5 | 6 — Heading level of the item headers (default 3)\nTypes the props use:\n- AccordionItem = { key: string; header: string; content: string; disabled?: boolean }\n  - key: Unique key\n  - header: Header content\n  - content: Panel content\n  - disabled: Whether disabled\nEvents (write @name={…}; the prop is onName):\n- @change(keys: string[]) — Change handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Accordion items={[]} />",
 "Alert": "## Alert — An inline message box: info, success, warning or error, optionally dismissible.\nTag: <Alert> (group: feedback)\nProps (? = optional):\n- variant?: \"info\" | \"success\" | \"warning\" | \"error\" — Alert variant\n- alertStyle?: \"filled\" | \"light\" | \"outline\" | \"subtle\" — Alert style\n- title?: string — Alert title\n- dismissible?: boolean — Whether the alert is dismissible\n- showIcon?: boolean — Show icon\n- borderRadius?: \"none\" | \"sm\" | \"md\" | \"lg\" | \"xl\" — Border radius\n- role?: \"alert\" | \"status\" | \"none\" — Announcement role. By default an error or a warning is an `alert` (read out at once) and info or success a `status` (read when the reader is free); `none` renders no live region, for an alert that is part of the page from the start.\n- children?: node — Alert content\nEvents (write @name={…}; the prop is onName):\n- @dismiss — Callback when dismissed\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Alert>…</Alert>",
 "AnimatedBox": "## AnimatedBox — Wraps children in an entrance or attention animation.\nTag: <AnimatedBox> (group: animation)\nProps (? = optional):\n- animation: \"fadeIn\" | \"fadeUp\" | \"fadeDown\" | \"fadeLeft\" | \"fadeRight\" | \"scaleIn\" | \"slideUp\" | \"slideDown\" | \"bounceIn\" — The animation preset to apply\n- trigger?: \"mount\" | \"visible\" | \"hover\" | \"state\" — What triggers the animation\n- isActive?: boolean — When trigger=\"state\", controls whether the animation is active\n- duration?: number — Duration of the animation in milliseconds\n- delay?: number — Delay before the animation starts in milliseconds\n- easing?: string — CSS easing function\n- children: node — Content to animate\nTypes the props use:\n- AnimationPreset = | 'fadeIn' | 'fadeUp' | 'fadeDown' | 'fadeLeft' | 'fadeRight' | 'scaleIn' | 'slideUp' | 'slideDown' | 'bounceIn'\n- AnimationTrigger = 'mount' | 'visible' | 'hover' | 'state'\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <AnimatedBox animation=\"fadeIn\">…</AnimatedBox>",
 "AnimatedNumber": "## AnimatedNumber — A number that counts up or down to its value.\nTag: <AnimatedNumber> (group: animation)\nProps (? = optional):\n- value: number — The target number to animate towards\n- duration?: number — Duration of the animation in milliseconds\n- prefix?: string — Text to display before the number\n- suffix?: string — Text to display after the number\n- decimals?: number — Number of decimal places\n- separator?: boolean — Whether to add thousand separators\n- trigger?: \"mount\" | \"visible\" — What triggers the animation to start\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <AnimatedNumber value={1} />",
 "App": "## App — The root of a page: theme and base layout. Every page's template starts with <App>.\nTag: <App> (group: essentials)\nProps (? = optional):\n- children?: node — App content\n- theme?: 'light' | 'dark' | string — Inherit the runtime/preview appearance by default; light/dark opt out.\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <App>…</App>\nFrom the docs (machine-learning-torch):\n```xml\n<logic src=\"../logic/main.py\" />\n\n<App>\n  <Stack direction=\"vertical\" gap=\"md\" padding=\"lg\">\n    <Text>Loss: {loss}</Text>\n    <Button variant=\"primary\" @click={() => train(50)}>Train 50 steps</Button>\n  </Stack>\n</App>\n```",
 "AreaChart": "## AreaChart — Filled line chart for one or more series.\nTag: <AreaChart> (group: charts)\nProps (? = optional):\n- series: AreaChartSeries[]\n- width?: number\n- height?: number\n- padding?: Partial<ChartPadding> | number\n- showGrid?: boolean\n- showXAxis?: boolean\n- showYAxis?: boolean\n- showLegend?: boolean\n- xAxisLabel?: string\n- yAxisLabel?: string\n- yMin?: number\n- yMax?: number\n- formatXLabel?: function\n- formatYLabel?: function\n- stacked?: boolean\n- gradient?: boolean\n- interactive?: boolean\n- ariaLabel?: string — Text alternative for the chart; a summary of its values by default\nTypes the props use:\n- AreaChartSeries = { name: string; data: DataPoint[]; color?: string; strokeWidth?: number; fillOpacity?: number; smooth?: boolean }\n- ChartPadding = { top: number; right: number; bottom: number; left: number }\n  The space a chart leaves around its plot, a number for each side.\n- DataPoint = { x: number | string; y: number; label?: string }\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <AreaChart series={[]} />",
 "AudioStream": "## AudioStream — Plays audio samples the logic produces, in real time.\nTag: <AudioStream> (group: media)\nProps (? = optional):\n- getSamples?: function — Called when the scheduler needs more audio. Receives the number of frames that would fill the lead buffer, and returns either a base64 string of interleaved PCM, an {@link AudioStreamBlock}, or `null`/`undefined` for \"nothing right now\". Returning nothing is a normal, cheap answer — the component simply asks again — and is the right answer when the producer has no samples ready. Do not pad with silence: silence inserted mid-stream lands as a click, whereas a short queue does not. May be synchronous or return a promise; script functions running in a worker are asynchronous and are awaited. Called on the component's own schedule, driven by how far ahead the queue runs — not on a frame timer. It keeps running while the tab is in the background, where `requestAnimationFrame` does not.\n- sampleRate?: number — Rate to ask the audio system for, in Hz (default 48000). A request, not a promise: the browser and the output device both get a say, and Safari refuses rates it cannot do natively rather than resampling. `onReady` reports the rate actually in use, and a producer should generate at that rate rather than assume this one.\n- channels?: 1 | 2 — Channels in the PCM the producer will send: 1 or 2 (default 2)\n- format?: \"i16\" | \"f32\" — Sample format of the PCM (default 'i16' — signed 16-bit, little-endian)\n- bufferMs?: number — Target lead buffer in milliseconds (default 80). The queue is kept roughly this far ahead of the playhead. Larger is safer — it is how much main-thread stall the stream survives without a gap — and smaller is more responsive, which matters when the audio answers an input. 80ms survives an ordinary garbage collection; below about 30ms an unlucky layout is audible.\n- running?: boolean — Whether the stream is pulling audio (default true)\n- muted?: boolean — Silence the output without stopping the stream (default false)\n- volume?: number — Output gain, 0..1 (default 1)\n- showControls?: boolean — Show the built-in status strip and the unlock button (default true)\n- unlockLabel?: string — Label on the button shown while the browser is blocking audio\n- children?: node — Rendered below the status strip\nTypes the props use:\n- AudioStreamResult = | string | number[] | AudioStreamBlock | null | undefined\n  What `getSamples` may hand back. `null`, `undefined` or 0 frames means silence.\n- PcmFormat = 'i16' | 'f32'\n  Sample formats the component understands, after normalisation.\n- AudioStreamReadyInfo = { sampleRate: number; channels: number; bufferMs: number; baseLatency: number }\n  - sampleRate: The rate the graph actually runs at. Identical to the first argument.\n  - channels: Channels the component will ask for by default.\n  - bufferMs: Target lead buffer, in milliseconds.\n  - baseLatency: The context's own processing latency, in seconds.\n- AudioStreamUnderrunInfo = { underruns: number; producerUnderruns: number; queuedMs: number; sampleRate: number }\n  - underruns: How many times this component has starved since it started.\n  - producerUnderruns: The producer's own counter, if it reported one.\n  - queuedMs: Audio still queued when the starvation was noticed, in milliseconds.\n  - sampleRate: The rate the graph is running at.\n- AudioStreamBlock = { pcm?: string | null; data?: string | null; samples?: number[] | null; frames?: number; rate?: number; sampleRate?: number; channels?: number; format?: string; underruns?: number }\n  A block of PCM, in the richer of the two shapes `getSamples` may return. The plain-string shape is the same thing with everything except `pcm` defaulted from the component's props. Producers that resample, that vary their block length, or that need to report starvation should return the object.\n  - pcm: Base64 of the interleaved PCM for this block.\n  - data: Accepted as an alias for `pcm`, for producers that named it `data`.\n  - samples: Interleaved samples as plain numbers, -1..1. An alternative to `pcm`.\n  - frames: Frames (one frame = one sample per channel) actually delivered. Authoritative when present, and worth sending: a producer whose frame count is fractional per video frame — 803.65 at 48kHz for a 59.7275Hz console — delivers a different count on consecutive calls, and a consumer that assumed a constant would drift.\n  - rate: Rate the PCM is at. Defaults to the context rate.\n  - sampleRate: Accepted as an alias for `rate`.\n  - channels: Channels interleaved in `pcm`. Defaults to the `channels` prop.\n  - format: `'i16'`/`'s16le'`/`'pcm16'` or `'f32'`/`'float32'`. Defaults to the `format` prop.\n  - underruns: The producer's own starvation counter, passed through to `onUnderrun`.\nEvents (write @name={…}; the prop is onName):\n- @ready(sampleRate: number, info: AudioStreamReadyInfo) — Called once the graph is actually running, with the real context rate. This is the moment a producer should configure itself: until it has fired there is no audio clock to match. The second argument carries the rest of the graph's shape for producers that need it.\n- @underrun(count: number, info: AudioStreamUnderrunInfo) — Called when the queue starves, at most a few times a second\n- @error(error: string) — Called when the audio graph cannot be built\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <AudioStream>…</AudioStream>",
 "Avatar": "## Avatar — A person's picture, or their initials when there is none.\nTag: <Avatar> (group: display)\nProps (? = optional):\n- src?: string — Image source\n- alt?: string — Alt text\n- name?: string — User name (for initials fallback)\n- size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl' | number — Avatar size\n- shape?: \"circle\" | \"square\" | \"rounded\" — Avatar shape\n- border?: boolean — Border\n- borderColor?: string — Border color\n- backgroundColor?: string — Background color (for initials)\n- textColor?: string — Text color (for initials)\n- status?: \"online\" | \"offline\" | \"away\" | \"busy\" | \"none\" — Online status indicator\n- statusPosition?: \"top-right\" | \"bottom-right\" | \"top-left\" | \"bottom-left\" — Status position\n- badge?: string | number — Badge content (number or text)\n- badgeColor?: string — Badge color\n- ring?: boolean — Show ring on hover\n- ringColor?: string — Ring color\n- ariaLabel?: string — Accessible label (for interactive avatars)\n- children?: node — Children (for custom content)\nEvents (write @name={…}; the prop is onName):\n- @click — Click handler\n- @keyDown(event) — Keyboard handler\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Avatar>…</Avatar>\nFrom the docs (components):\n```xml\n<DescriptionList items={[{ label: \"Customer\", value: order.name }, { label: \"Paid\", value: order.paid }]} columns={2} />\n\n<Field label=\"Volume\" hint=\"Applies to every sound.\" error={volumeError}>\n  <Slider :bind={volume} />\n</Field>\n\n<ButtonGroup ariaLabel=\"Range\">\n  <Button @click={() => range = \"day\"}>Day</Button>\n  <Button @click={() => range = \"week\"}>Week</Button>\n</ButtonGroup>\n\n<CopyButton value={inviteLink} label=\"Copy invite\" />\n\n<Confirm open={asking} title=\"Delete this note?\" message=\"This cannot be undone.\"\n         confirmText=\"Delete\" variant=\"danger\"\n         @confirm={() => remove()} @cancel={() => asking = false} />\n\n<AvatarGroup max={3}>\n  #each (person in people) key={person.id}\n    <Avatar name={person.name} />\n  #end\n</AvatarGroup>\n```",
 "AvatarGroup": "## AvatarGroup — Avatars overlapping in a row, with +N for the rest; put Avatar tags (or an #each of them) inside.\nTag: <AvatarGroup> (group: display)\nAvatarGroup - Displays avatars in a stacked group\nProps (? = optional):\n- max?: number — Maximum avatars to show\n- size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl' | number — Avatar size\n- spacing?: number — Spacing between avatars (negative for overlap)\n- borderColor?: string — Border color for overlapping avatars\n- children: node — Children (Avatar components)\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <AvatarGroup>…</AvatarGroup>\nFrom the docs (components):\n```xml\n<DescriptionList items={[{ label: \"Customer\", value: order.name }, { label: \"Paid\", value: order.paid }]} columns={2} />\n\n<Field label=\"Volume\" hint=\"Applies to every sound.\" error={volumeError}>\n  <Slider :bind={volume} />\n</Field>\n\n<ButtonGroup ariaLabel=\"Range\">\n  <Button @click={() => range = \"day\"}>Day</Button>\n  <Button @click={() => range = \"week\"}>Week</Button>\n</ButtonGroup>\n\n<CopyButton value={inviteLink} label=\"Copy invite\" />\n\n<Confirm open={asking} title=\"Delete this note?\" message=\"This cannot be undone.\"\n         confirmText=\"Delete\" variant=\"danger\"\n         @confirm={() => remove()} @cancel={() => asking = false} />\n\n<AvatarGroup max={3}>\n  #each (person in people) key={person.id}\n    <Avatar name={person.name} />\n  #end\n</AvatarGroup>\n```",
 "Badge": "## Badge — A small count or status label.\nTag: <Badge> (group: essentials)\nProps (? = optional):\n- variant?: \"default\" | \"primary\" | \"secondary\" | \"success\" | \"warning\" | \"danger\" | \"info\" — Badge variant\n- badgeStyle?: \"solid\" | \"subtle\" | \"outline\" — Badge style\n- size?: \"xs\" | \"sm\" | \"md\" | \"lg\" — Badge size\n- pill?: boolean — Whether it's a pill shape\n- dot?: boolean — Whether it's just a dot\n- content?: string | number — Content (number or text)\n- max?: number — Maximum count (for numbers)\n- leftIcon?: node — Left icon\n- rightIcon?: node — Right icon\n- pulse?: boolean — Pulse animation (for notifications)\n- glow?: boolean — Glow effect\n- children?: node — Children\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Badge>…</Badge>",
 "BarChart": "## BarChart — Vertical or horizontal bar chart; grouped or stacked series.\nTag: <BarChart> (group: charts)\nProps (? = optional):\n- series: BarChartSeries[]\n- width?: number\n- height?: number\n- padding?: Partial<ChartPadding> | number\n- orientation?: \"vertical\" | \"horizontal\"\n- grouped?: boolean\n- stacked?: boolean\n- barPadding?: number\n- groupPadding?: number\n- showGrid?: boolean\n- showValues?: boolean\n- showLegend?: boolean\n- formatValue?: function\n- interactive?: boolean\n- ariaLabel?: string — Text alternative for the chart; a summary of its values by default\nTypes the props use:\n- BarChartSeries = { name: string; data: BarDataPoint[]; color?: string }\n- ChartPadding = { top: number; right: number; bottom: number; left: number }\n  The space a chart leaves around its plot, a number for each side.\n- BarDataPoint = { label: string; value: number; color?: string }\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <BarChart series={[]} />",
 "Box": "## Box — A plain box with padding, background, border, radius and shadow props.\nTag: <Box> (group: essentials)\nProps (? = optional):\n- padding?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Padding\n- margin?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Margin\n- background?: string — Background color\n- borderRadius?: 'none' | 'sm' | 'md' | 'lg' | 'full' | string — Border radius\n- border?: string — Border\n- shadow?: 'none' | 'sm' | 'md' | 'lg' | 'xl' | string — Shadow\n- flex?: number | string — Flex value\n- overflow?: \"visible\" | \"hidden\" | \"scroll\" | \"auto\" — Overflow\n- width?: string — Width\n- height?: string — Height\n- minWidth?: string — Min width\n- minHeight?: string — Min height\n- maxWidth?: string — Max width\n- maxHeight?: string — Max height\n- children?: node — Children\nEvents (write @name={…}; the prop is onName):\n- @click(event) — Click handler\n- @keyDown(event) — Keyboard handler\n- @pointerDown(event) — Pointer handlers, forwarded to the element. A template binds them as `@pointerdown` / `@pointerup` / `@pointermove` / `@pointercancel` / `@pointerleave`, which is how an app gets a press-and-release pair or a swipe out of a plain box. None of them make the box focusable or give it a button role; only `onClick` does that.\n- @pointerUp(event)\n- @pointerMove(event)\n- @pointerCancel(event)\n- @pointerLeave(event)\n- @contextMenu(event) — Context-menu handler; a hold-to-press control uses it to swallow the long-press menu.\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Box>…</Box>\nFrom the docs (ui-language):\n```xml\n<div class=\"row\" class:is-selected={row.id === selectedId}>…</div>\n<Text style:color={overdue ? \"crimson\" : undefined}>{due}</Text>\n<Box style=\"padding: 1rem\" style:--accent={theme.accent} style:opacity={busy && 0.5} />\n```",
 "Breadcrumb": "## Breadcrumb — The path to the current page, as links.\nTag: <Breadcrumb> (group: navigation)\nProps (? = optional):\n- items: BreadcrumbItem[] — Breadcrumb items\n- separator?: node — Separator character or element\n- size?: \"sm\" | \"md\" | \"lg\" — Size\nTypes the props use:\n- BreadcrumbItem = { label: string; href?: string; onClick?: () => void; icon?: string }\n  - label: Item label\n  - href: Link href\n  - onClick: Click handler\n  - icon: Icon\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Breadcrumb items={[]} />",
 "Button": "## Button — A clickable button: variants, sizes, loading and disabled states.\nTag: <Button> (group: essentials)\nProps (? = optional):\n- type?: \"button\" | \"submit\" | \"reset\" — Button type\n- variant?: \"primary\" | \"secondary\" | \"outline\" | \"danger\" | \"success\" | \"warning\" | \"ghost\" | \"link\" — Button variant\n- size?: \"xs\" | \"sm\" | \"md\" | \"lg\" | \"xl\" — Button size\n- disabled?: boolean — Whether the button is disabled\n- loading?: boolean — Whether the button is loading\n- fullWidth?: boolean — Full width\n- rounded?: boolean — Rounded style (pill shape)\n- iconOnly?: boolean — Icon only button (square aspect ratio)\n- leftIcon?: node — Left icon\n- rightIcon?: node — Right icon\n- ariaLabel?: string — Accessible name. Required in practice for `iconOnly` buttons and for any button whose whole label is a glyph — a screen reader reads \"+\" as nothing useful, and until this existed there was no way for a template to say what such a button does.\n- aria-label?: string — Alias, for hosts that pass DOM attribute names straight through.\n- title?: string — Native tooltip.\n- children?: node — Children\nEvents (write @name={…}; the prop is onName):\n- @click(event) — Click handler\n- @pointerDown(event) — Pointer handlers, forwarded to the element. `onClick` fires on release; a control that has to know about the press itself (an emulator's A button, held through a jump) binds `@pointerdown` and `@pointerup` too.\n- @pointerUp(event)\n- @pointerCancel(event)\n- @pointerLeave(event)\n- @contextMenu(event) — Context-menu handler; a hold-to-press control swallows the long-press menu with it.\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Button>…</Button>\nFrom the docs (first-app):\n```xml\n<Button @click={() => reset()}>Reset</Button>\n```",
 "ButtonGroup": "## ButtonGroup — Buttons that belong together, joined edge to edge; put Button tags inside. For one choice of a few, use SegmentedControl.\nTag: <ButtonGroup> (group: controls)\nProps (? = optional):\n- orientation?: \"horizontal\" | \"vertical\" — Side by side, or one above the other\n- attached?: boolean — Joined edge to edge. False keeps them apart with a small gap\n- fullWidth?: boolean — Fill the width, each button taking an equal share\n- ariaLabel?: string — What the group is for, read by a screen reader\n- children?: node — The buttons\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <ButtonGroup>…</ButtonGroup>\nFrom the docs (components):\n```xml\n<DescriptionList items={[{ label: \"Customer\", value: order.name }, { label: \"Paid\", value: order.paid }]} columns={2} />\n\n<Field label=\"Volume\" hint=\"Applies to every sound.\" error={volumeError}>\n  <Slider :bind={volume} />\n</Field>\n\n<ButtonGroup ariaLabel=\"Range\">\n  <Button @click={() => range = \"day\"}>Day</Button>\n  <Button @click={() => range = \"week\"}>Week</Button>\n</ButtonGroup>\n\n<CopyButton value={inviteLink} label=\"Copy invite\" />\n\n<Confirm open={asking} title=\"Delete this note?\" message=\"This cannot be undone.\"\n         confirmText=\"Delete\" variant=\"danger\"\n         @confirm={() => remove()} @cancel={() => asking = false} />\n\n<AvatarGroup max={3}>\n  #each (person in people) key={person.id}\n    <Avatar name={person.name} />\n  #end\n</AvatarGroup>\n```",
 "Camera": "## Camera — Live camera view that can capture a photo or video (needs the camera permission).\nTag: <Camera> (group: media)\nProps (? = optional):\n- mode?: \"photo\" | \"video\" | \"live\" — Operating mode (default 'photo')\n- facing?: \"user\" | \"environment\" — Camera facing mode (default 'user')\n- width?: number — Video width in pixels (default 640)\n- height?: number — Video height in pixels (default 480)\n- frameRate?: number — Frame rate for live mode, in fps (default 10)\n- quality?: number — JPEG quality 0-1 (default 0.7)\n- active?: boolean — Whether the camera is active (default true)\n- audio?: boolean — Whether to capture sound as well as pictures (default: true in `video` mode, false otherwise). Sound is the microphone, which is its own capability: a bundle that declares `camera` alone gets silent video, and one that wants a soundtrack declares `mic` too.\n- showControls?: boolean — Whether to show built-in controls (default true)\n- children?: node — Children rendered as overlay\nEvents (write @name={…}; the prop is onName):\n- @capture(data: { dataUrl: string; width: number; height: number }) — Called when a photo is captured\n- @frame(data: { dataUrl: string; width: number; height: number; timestamp: number }) — Called on each live frame\n- @record(data: { dataUrl: string; duration: number; mimeType: string }) — Called when video recording completes\n- @error(error: string) — Called when an error occurs\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Camera>…</Camera>",
 "Card": "## Card — A bordered or elevated panel, with an optional title and subtitle.\nTag: <Card> (group: essentials)\nProps (? = optional):\n- title?: string — Card title (shown in header)\n- subtitle?: string — Card subtitle\n- variant?: \"default\" | \"outlined\" | \"elevated\" | \"filled\" | \"ghost\" | \"glass\" | \"gradient\" — Card variant\n- padding?: 'none' | 'sm' | 'md' | 'lg' | 'xl' | string — Padding\n- borderRadius?: 'none' | 'sm' | 'md' | 'lg' | 'xl' | string — Border radius\n- hover?: boolean — Whether the card is interactive (hoverable) - shorthand for interactive\n- interactive?: boolean — Whether the card is interactive (hoverable)\n- selected?: boolean — Whether the card is selected\n- gradientFrom?: string — Gradient background colors (for gradient variant)\n- gradientTo?: string\n- header?: node — Header content (replaces title)\n- footer?: node — Footer content\n- headerActions?: node — Header actions (right side of header)\n- dividers?: boolean — Whether to show dividers\n- children?: node — Children\nEvents (write @name={…}; the prop is onName):\n- @click(event) — Click handler (makes card interactive)\n- @keyDown(event) — Keyboard handler\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Card>…</Card>\nFrom the docs (ui-language):\n```xml\n<form @submit.prevent={() => save()}>\n  <Input :bind={title} @keydown.enter={() => save()} @keydown.escape={() => cancel()} />\n</form>\n<Box className=\"backdrop\" @click.self={() => close()}>\n  <Card @click.stop={() => select(item)}>…</Card>\n</Box>\n```",
 "Center": "## Center — Centres its children horizontally and vertically.\nTag: <Center> (group: essentials)\nProps (? = optional):\n- inline?: boolean — Whether to center inline (horizontal only)\n- width?: string — Width\n- height?: string — Height\n- padding?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Padding\n- children?: node — Children\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Center>…</Center>",
 "Checkbox": "## Checkbox — A checkbox with a label; :bind={name} holds true or false. checked={x} only shows x.\nTag: <Checkbox> (group: controls)\nProps (? = optional):\n- name?: string — Input name\n- checked?: boolean — Whether checked\n- defaultChecked?: boolean — Default checked state\n- indeterminate?: boolean — Indeterminate state\n- label?: string — Label text\n- description?: string — Description text below label\n- disabled?: boolean — Whether the input is disabled\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- error?: boolean — Error state\nEvents (write @name={…}; the prop is onName):\n- @change(event) — Change handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Checkbox />\nFrom the docs (ui-language):\n```xml\n#each (todo in todos) key={todo.id}\n  <Checkbox :bind={todo.done} label={todo.title} />\n  <Button @click={() => todo.count++}>More</Button>\n#end\n\n#each ({ id, title }, i in tasks) key={id}\n  <Text>{i + 1}. {title}</Text>\n#end\n\n#each ([name, total] in Object.entries(totals))\n  <Text>{name}: {total}</Text>\n#end\n\n#each (star in 5)\n  <Icon name=\"star\" />\n#end\n```",
 "CodeEditor": "## CodeEditor — An editor for source code with syntax highlighting.\nTag: <CodeEditor> (group: editors)\nProps (? = optional):\n- value?: string — Current value\n- defaultValue?: string — Default value\n- language?: \"javascript\" | \"typescript\" | \"json\" | \"html\" | \"css\" | \"python\" | \"sql\" | \"markdown\" | \"plain\" — Language for syntax highlighting\n- placeholder?: string — Placeholder text\n- disabled?: boolean — Whether the editor is disabled\n- readOnly?: boolean — Whether the editor is read-only\n- lineNumbers?: boolean — Show line numbers\n- tabSize?: number — Tab size\n- minHeight?: string — Minimum height\n- maxHeight?: string — Maximum height\n- ariaLabel?: string — Accessible name for the text field, when no visible label names it\n- aria-label?: string — Accessible name (DOM attribute spelling)\nEvents (write @name={…}; the prop is onName):\n- @change(value: string) — Change handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <CodeEditor />",
 "Collapse": "## Collapse — Shows or hides its children with an animation.\nTag: <Collapse> (group: navigation)\nProps (? = optional):\n- isOpen: boolean — Whether content is visible\n- duration?: number — Collapse duration in ms\n- children?: node — Content\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Collapse isOpen={true}>…</Collapse>",
 "ColorPicker": "## ColorPicker — Choose a colour, with optional presets.\nTag: <ColorPicker> (group: pickers)\nProps (? = optional):\n- value?: string — Current color value (hex)\n- defaultValue?: string — Default value\n- name?: string — Input name\n- label?: string — Label text\n- disabled?: boolean — Whether disabled\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- presets?: string[] — Preset colors to show\n- showInput?: boolean — Show text input for hex value\n- fullWidth?: boolean — Full width\nEvents (write @name={…}; the prop is onName):\n- @change(color: string) — Change handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <ColorPicker />",
 "Confirm": "## Confirm — Asks \"are you sure?\" before something is done: open={asking}, @confirm and @cancel. The app closes it by setting open.\nTag: <Confirm> (group: feedback)\nProps (? = optional):\n- open?: boolean — Whether the question is being asked\n- title?: string — The question\n- message?: node — What will happen, under the question. Content inside the tag is shown after it\n- confirmText?: string — The answer that goes ahead\n- cancelText?: string — The answer that does not\n- variant?: \"primary\" | \"danger\" | \"warning\" | \"success\" — How the go-ahead button looks: `danger` for something that cannot be undone\n- loading?: boolean — The action is under way: both answers are held and the go-ahead button shows it\n- size?: \"sm\" | \"md\" | \"lg\" — Dialog size\n- children?: node — More to say, after the message\nEvents (write @name={…}; the prop is onName):\n- @confirm — Called when the person goes ahead\n- @cancel — Called when they do not: the other button, Escape, or a click outside\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Confirm>…</Confirm>\nFrom the docs (ui-language):\n```xml\n<Button @click={() => adding = true}>New task</Button>\n<Modal :bind={adding} title=\"New task\">…</Modal>\n<Confirm :bind={asking} title=\"Delete this task?\" @confirm={() => remove(task)} />\n<Tabs :bind={tab} tabs={[{ key: \"open\", label: \"Open\" }, { key: \"done\", label: \"Done\" }]} />\n<Pagination :bind={page} totalPages={pages} />\n```",
 "Container": "## Container — Centres content at a maximum width (sm to xl).\nTag: <Container> (group: essentials)\nProps (? = optional):\n- size?: \"sm\" | \"md\" | \"lg\" | \"xl\" | \"2xl\" | \"full\" — Max width size\n- centered?: boolean — Center the container\n- padding?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Padding\n- children?: node — Children\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Container>…</Container>",
 "Content": "## Content — The main content region of a Layout, optionally per route.\nTag: <Content> (group: essentials)\nProps (? = optional):\n- children?: node — Content\n- route?: string — Route name (for conditional rendering)\n- padding?: 'none' | 'sm' | 'md' | 'lg' | 'xl' | string — Padding\n- background?: string — Background color\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Content>…</Content>",
 "Controls": "## Controls — What the player holds, as one record: :bind={pad} with keys={{ left: \"ArrowLeft a\", fire: \"Space\" }} gives pad.left and pad.presses.fire. Keeps those keys from the browser, reads a gamepad, draws nothing.\nTag: <Controls> (group: games)\nProps (? = optional):\n- keys?: Record<string, string | string[]> — The actions and the keys that hold each, by the action's name: `{ left: \"ArrowLeft a\", right: \"ArrowRight d\", fire: \"Space\" }`. A key is named as `KeyboardEvent.key` or `KeyboardEvent.code` gives it (`\"ArrowLeft\"`, `\"a\"`, `\"Space\"`, `\"Enter\"`, `\"ShiftLeft\"`), several separated by spaces or as a list; a letter is the same key with Shift held. A letter or a digit is the key that types it; on a keyboard that types other letters there (Russian, Greek) it is the key where that letter usually is, so `w a s d` are the same four keys. Only these keys are kept from the browser.\n- value?: ControlsValue | null — The record of what is held. Write `:bind={pad}` over a variable that starts as `{ presses: {} }`: the component fills it in and keeps it. Bound to the same variable as a `<DPad>` or another `<Controls>`, an action is held while any of them holds it.\n- gamepad?: boolean | Record<string, number | number[]> — A connected gamepad's part (default true): its left stick and d-pad hold the actions named `left`, `right`, `up` and `down`, and buttons 0, 1, 2… (A, B, X, Y on the usual layout) hold the other actions in the order `keys` lists them. A record names the buttons instead, by action: `{ fire: 0, jump: [1, 2] }`. `false` reads no gamepad. What the gamepad held is let go when it is turned off, unplugged, or its buttons are named anew.\n- deadzone?: number — How far the stick is pushed, from 0 to 1, before it holds a direction (default 0.4). It lets go when the stick falls back under four fifths of that, so a stick resting at the edge is one press and not many.\n- enabled?: boolean — Whether the controls are listening (default true). While false nothing is held and no key is kept from the browser: for a menu over the game, where the arrows should move through the page again.\nTypes the props use:\n- ControlsValue = { presses: Record<string, number>; [action: string]: boolean | Record<string, number> }\n  What a `<Controls>` (and a `<DPad>`) keeps in the variable it is bound to.\n  - presses: How many times each action has been pressed since the app started, by the action's name. A press counts once however long it is held, so a tick that remembers the count it last saw can tell a new press: `if (pad.presses.fire > fired) { fired = pad.presses.fire; shoot() }`.\nEvents (write @name={…}; the prop is onName):\n- @change(value: ControlsValue) — Called with the new record when an action is pressed or let go; `:bind` writes it to the variable.\n- @press(action: string) — Called once when a key or the gamepad puts an action down, with its name; not again while it is held, by these or by a `<DPad>` bound to the same variable.\n- @release(action: string) — Called once when a key or the gamepad lets an action go and nothing else holds it, with its name.\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Controls />\nFrom the docs (threejs-games):\n```xml\n<Controls :bind={pad} keys={{ left: \"ArrowLeft a\", right: \"ArrowRight d\", start: \"Space Enter\" }} @press={pressed} />\n```",
 "CopyButton": "## CopyButton — A button that copies its value to the clipboard and says \"Copied\" for a moment; use it instead of a logic function and a state variable for the label.\nTag: <CopyButton> (group: controls)\nProps (? = optional):\n- value?: string | number | null — The text to copy\n- label?: node — What the button says (default \"Copy\")\n- copiedLabel?: node — What it says once it has copied (default \"Copied\")\n- iconOnly?: boolean — The icon alone; the label is read out\n- variant?: ButtonProps['variant'] — Visual style, as Button's\n- size?: ButtonProps['size'] — Size, as Button's\n- resetAfter?: number — How long it says it has copied, in milliseconds (default 2000)\n- disabled?: boolean — Disabled state\n- children?: node — In place of `label`\nTypes the props use:\n- ButtonProps = {\n    type?: 'button' | 'submit' | 'reset' — Button type\n    variant?: | 'primary' | 'secondary' | 'outline' | 'danger' | 'success' | 'warning' | 'ghost' | 'link' — Button variant\n    size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl' — Button size\n    disabled?: boolean — Whether the button is disabled\n    loading?: boolean — Whether the button is loading\n    fullWidth?: boolean — Full width\n    rounded?: boolean — Rounded style (pill shape)\n    iconOnly?: boolean — Icon only button (square aspect ratio)\n    leftIcon?: string — Left icon\n    rightIcon?: string — Right icon\n    onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void — Click handler\n    ariaLabel?: string — Accessible name. Required in practice for `iconOnly` buttons and for any button whose whole label is a glyph — a screen reader reads \"+\" as nothing useful, and until this existed there was no way for a template to say what such a button does.\n    'aria-label'?: string — Alias, for hosts that pass DOM attribute names straight through.\n    title?: string — Native tooltip.\n    onPointerDown?: (event: React.PointerEvent<HTMLButtonElement>) => void — Pointer handlers, forwarded to the element. `onClick` fires on release; a control that has to know about the press itself (an emulator's A button, held through a jump) binds `@pointerdown` and `@pointerup` too.\n    onPointerUp?: (event: React.PointerEvent<HTMLButtonElement>) => void\n    onPointerCancel?: (event: React.PointerEvent<HTMLButtonElement>) => void\n    onPointerLeave?: (event: React.PointerEvent<HTMLButtonElement>) => void\n    onContextMenu?: (event: React.MouseEvent<HTMLButtonElement>) => void — Context-menu handler; a hold-to-press control swallows the long-press menu with it.\n    className?: string — Additional CSS class\n    style?: React.CSSProperties — Inline styles\n    children?: string — Children\n  }\nEvents (write @name={…}; the prop is onName):\n- @copy(text: string) — Called with the text once it is on the clipboard\n- @error(reason: string) — Called when the browser would not copy\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <CopyButton>…</CopyButton>\nFrom the docs (components):\n```xml\n<DescriptionList items={[{ label: \"Customer\", value: order.name }, { label: \"Paid\", value: order.paid }]} columns={2} />\n\n<Field label=\"Volume\" hint=\"Applies to every sound.\" error={volumeError}>\n  <Slider :bind={volume} />\n</Field>\n\n<ButtonGroup ariaLabel=\"Range\">\n  <Button @click={() => range = \"day\"}>Day</Button>\n  <Button @click={() => range = \"week\"}>Week</Button>\n</ButtonGroup>\n\n<CopyButton value={inviteLink} label=\"Copy invite\" />\n\n<Confirm open={asking} title=\"Delete this note?\" message=\"This cannot be undone.\"\n         confirmText=\"Delete\" variant=\"danger\"\n         @confirm={() => remove()} @cancel={() => asking = false} />\n\n<AvatarGroup max={3}>\n  #each (person in people) key={person.id}\n    <Avatar name={person.name} />\n  #end\n</AvatarGroup>\n```",
 "DataGrid": "## DataGrid — A large, virtualised data table with sorting and selection.\nTag: <DataGrid> (group: data)\nProps (? = optional):\n- columns?: Array<DataGridColumn<T> | string> — The columns; without them, a column for each field of the rows\n- data?: T[]\n- keyField?: keyof T | ((row: T) => string | number)\n- height?: number | string\n- rowHeight?: number\n- headerHeight?: number\n- virtualized?: boolean\n- bordered?: boolean\n- striped?: boolean\n- hoverable?: boolean\n- sortKey?: string\n- sortDirection?: \"asc\" | \"desc\"\n- filters?: Record<string, string | number> — What was typed into each column's filter input, by column key.\n- selectedKeys?: Set<string | number>\n- selectionMode?: \"none\" | \"single\" | \"multiple\"\n- loading?: boolean\n- emptyMessage?: node\n- ariaLabel?: string — Accessible name for the grid\nTypes the props use:\n- DataGridColumn = {\n    key: string\n    header: string\n    width?: number | string\n    minWidth?: number\n    maxWidth?: number\n    align?: 'left' | 'center' | 'right'\n    sortable?: boolean\n    filterable?: boolean\n    editable?: boolean\n    frozen?: boolean\n    resizable?: boolean\n    accessor?: keyof T | ((row: T) => unknown)\n    render?: (value: unknown, row: T, index: number) => string\n    editor?: (props: CellEditorProps<T>) => string\n    filterType?: 'text' | 'number' | 'select' | 'date'\n    filterOptions?: { label: string; value: string | number }[]\n  }\n- CellEditorProps = { value: unknown; row: T; column: DataGridColumn<T>; onSave: (value: unknown) => void; onCancel: () => void }\nEvents (write @name={…}; the prop is onName):\n- @sort(key: string, direction: 'asc' | 'desc')\n- @filterChange(filters: Record<string, string | number>)\n- @selectionChange(keys: Set<string | number>)\n- @cellEdit(key: string | number, columnKey: string, value: unknown)\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <DataGrid />",
 "DatePicker": "## DatePicker — Choose a date.\nTag: <DatePicker> (group: pickers)\nProps (? = optional):\n- value?: string | Date | number — Current date value (ISO string or Date object)\n- defaultValue?: string | Date | number — Default value\n- name?: string — Input name\n- label?: string — Label text\n- placeholder?: string — Placeholder text\n- disabled?: boolean — Whether disabled\n- readOnly?: boolean — Whether read-only\n- required?: boolean — Whether required\n- min?: string | Date | number — Minimum date\n- max?: string | Date | number — Maximum date\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- fullWidth?: boolean — Full width\n- error?: boolean | string — Error state or message\n- format?: \"yyyy-mm-dd\" | \"mm/dd/yyyy\" | \"dd/mm/yyyy\" — Date format for display\nEvents (write @name={…}; the prop is onName):\n- @change(date: string | null, dateString: string) — Change handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <DatePicker />",
 "DescriptionList": "## DescriptionList — The facts about one record as labels and values: items={[{ label, value }]} or a record whose keys are the labels.\nTag: <DescriptionList> (group: display)\nProps (? = optional):\n- items?: DescriptionItem[] | Record<string, unknown> — The fields: a list of { label, value, hint? }, or a record whose keys are the labels\n- columns?: number — Fields side by side, 1 to 4. They fall to fewer where there is not the room\n- layout?: \"stacked\" | \"inline\" — Label above its value, or beside it\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- dividers?: boolean — A line between one field and the next\n- emptyText?: string — What stands in for a value that is not there\n- labelWidth?: string — Width of the label column in the inline layout, as CSS\nTypes the props use:\n- DescriptionItem = { label: string; value?: string; hint?: string }\n  - label: What the value is\n  - value: The value. Nothing, an empty text or an empty list is shown as `emptyText`\n  - hint: A note under the value\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <DescriptionList />\nFrom the docs (components):\n```xml\n<DescriptionList items={[{ label: \"Customer\", value: order.name }, { label: \"Paid\", value: order.paid }]} columns={2} />\n\n<Field label=\"Volume\" hint=\"Applies to every sound.\" error={volumeError}>\n  <Slider :bind={volume} />\n</Field>\n\n<ButtonGroup ariaLabel=\"Range\">\n  <Button @click={() => range = \"day\"}>Day</Button>\n  <Button @click={() => range = \"week\"}>Week</Button>\n</ButtonGroup>\n\n<CopyButton value={inviteLink} label=\"Copy invite\" />\n\n<Confirm open={asking} title=\"Delete this note?\" message=\"This cannot be undone.\"\n         confirmText=\"Delete\" variant=\"danger\"\n         @confirm={() => remove()} @cancel={() => asking = false} />\n\n<AvatarGroup max={3}>\n  #each (person in people) key={person.id}\n    <Avatar name={person.name} />\n  #end\n</AvatarGroup>\n```",
 "Divider": "## Divider — A horizontal or vertical rule, optionally labelled.\nTag: <Divider> (group: essentials)\nProps (? = optional):\n- direction?: \"horizontal\" | \"vertical\" — Direction of the divider\n- thickness?: string — Thickness of the line\n- color?: string — Color of the line\n- margin?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Margin around the divider\n- label?: string — Label in the middle\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Divider />",
 "DPad": "## DPad — An on-screen directional pad for games: press and release per direction, or :bind={pad} to the record a Controls keeps.\nTag: <DPad> (group: games)\nAn on-screen directional pad. Each direction is held, not clicked: `onPress` when a pointer or key goes down, `onRelease` when it comes up. A release is sent once per press — and also when the pointer is cancelled, leaves the button while pressed, the button loses focus, or the pad unmounts — so a character is never left walking. Enter and Space hold a focused direction like a pointer does. Bound with `:bind={pad}` it also keeps a record of what is held, the same one a `<Controls>` keeps for keys and a gamepad. In that record a direction is held while anything holds it: with the Left key still down, lifting the finger from the pad's Left leaves `pad.left` true.\nProps (? = optional):\n- value?: DPadValue | null — A record of what is held, the one a `<Controls>` keeps. Write `:bind={pad}`: `pad.left`, `pad.right`, `pad.up` and `pad.down` are true while that direction is held, and `pad.presses.left` counts its presses. Bound to the same variable as a `<Controls>`, touch and keys are one record to the game: a direction is held while a button here, a key or a gamepad holds it, and a press is counted once however many of them go down together.\n- buttonSize?: number — The side of each button in pixels (default 56)\n- color?: string — The buttons' colour (default a translucent grey that shows over light and dark alike)\n- visible?: boolean — Whether the pad is drawn (default true); hidden, whatever was held is let go\n- ariaLabel?: string — Accessible name for the pad as a whole\nTypes the props use:\n- DPadValue = { presses?: Record<string, number> } & Record<string, unknown>\n  The record a bound pad keeps: each direction while it is held, and how often each was pressed.\n- Direction = 'up' | 'down' | 'left' | 'right'\nEvents (write @name={…}; the prop is onName):\n- @press(direction: Direction) — Called when a direction goes down, with `\"up\"`, `\"down\"`, `\"left\"` or `\"right\"`\n- @release(direction: Direction) — Called when a direction is let go, with the direction\n- @change(value: DPadValue) — Called with the new record when a direction is pressed or let go; `:bind` writes it to the variable.\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <DPad />\nFrom the docs (threejs-games):\n```xml\n<logic>\n  // Dodge: slide left and right, and let the rocks go past.\n  let W = 320\n  let H = 440\n  let pad = { presses: {} }          // what the player holds; <Controls> and <DPad> keep it\n  let player = { x: 140, y: 400, w: 40, h: 16 }\n  let rocks = []\n  let score = 0\n  let best = 0\n  let playing = false\n  let paused = false\n  let over = false\n  let nextId = 1\n  let spawnIn = 0\n\n  function _init() {\n    best = Number(localStorage.getItem(\"dodge:best\")) || 0\n  }\n\n  function start() {\n    if (!paused) {\n      rocks = []\n      score = 0\n      spawnIn = 0\n      player.x = (W - player.w) / 2\n    }\n    over = false\n    paused = false\n    playing = true\n  }\n\n  // Two boxes overlap when neither is wholly to one side of the other.\n  function overlaps(a, b) {\n    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y\n  }\n\n  // One step of the game. dt is the seconds since the last step, so every\n  // speed is in pixels a second and the game runs the same on any screen.\n  function step(dt) {\n    const direction = (pad.right ? 1 : 0) - (pad.left ? 1 : 0)\n    player.x = Math.max(0, Math.min(W - player.w, player.x + direction * 240 * dt))\n\n    spawnIn -= dt\n    if (spawnIn <= 0) {\n      rocks.push({ id: nextId++, x: Math.random() * (W - 20), y: -20, w: 20, h: 20, speed: 120 + Math.random() * 140 })\n      spawnIn = 0.45\n    }\n    for (const rock of rocks) rock.y += rock.speed * dt\n\n    if (rocks.some(rock => overlaps(rock, player))) {\n      playing = false\n      over = true\n      if (score > best) {\n        best = score\n        localStorage.setItem(\"dodge:best\", String(best))\n      }\n      return\n    }\n\n    const before = rocks.length\n    rocks = rocks.filter(rock => rock.y < H)\n    score += before - rocks.length\n  }\n\n  // <Controls> calls this once for each press of an action, by its name.\n  function pressed(action) {\n    if (action === \"start\" && !playing) start()\n  }\n\n  // The app went to the background: nobody can see the rocks coming.\n  function _onHide() {\n    if (playing) {\n      playing = false\n      paused = true\n    }\n  }\n</logic>\n\n<style>\n  /* `flex: none` keeps the field its full height on a short screen: the page scrolls, where the field was squeezed and the player cut off. */\n  .field { position: relative; flex: none; overflow: hidden; background: #0f172a; border-radius: 8px; }\n  .player { position: absolute; background: #38bdf8; border-radius: 4px; }\n  .rock { position: absolute; background: #f97316; border-radius: 50%; }\n  .banner { position: absolute; inset: 0; display: grid; place-items: center; color: #e2e8f0; font-weight: 600; }\n</style>\n\n<App theme=\"dark\">\n  <Stack direction=\"vertical\" gap=\"md\" padding=\"lg\" align=\"center\" style=\"height: 100%; overflow: auto\">\n    <Heading level={1}>Dodge</Heading>\n    <Text>Score {score} · Best {best}</Text>\n\n    <Controls :bind={pad} keys={{ left: \"ArrowLeft a\", right: \"ArrowRight d\", start: \"Space Enter\" }} @press={pressed} />\n    <Loop frame running={playing} @tick={step} />\n\n    <div class=\"field\" style:width={W + \"px\"} style:height={H + \"px\"}>\n      <div class=\"player\" style:left={player.x + \"px\"} style:top={player.y + \"px\"} style:width={player.w + \"px\"} style:height={player.h + \"px\"}></div>\n      #each (rock in rocks) key={rock.id}\n        <div class=\"rock\" style:left={rock.x + \"px\"} style:top={rock.y + \"px\"} style:width={rock.w + \"px\"} style:height={rock.h + \"px\"}></div>\n      #end\n      #if (!playing)\n        <div class=\"banner\">{over ? \"Hit! Press Space to play again\" : paused ? \"Paused. Press Space to go on\" : \"Press Space to start\"}</div>\n      #end\n    </div>\n\n    <Stack direction=\"horizontal\" gap=\"md\" align=\"center\">\n      <DPad :bind={pad} buttonSize={48} />\n      <Button variant=\"primary\" @click={start}>{over ? \"Play again\" : paused ? \"Resume\" : \"Start\"}</Button>\n    </Stack>\n  </Stack>\n</App>\n```",
 "Draggable": "## Draggable — Makes its children draggable within bounds.\nTag: <Draggable> (group: animation)\nProps (? = optional):\n- axis?: \"both\" | \"x\" | \"y\" — Constrain drag axis\n- bounds?: 'parent' | DragBounds — Constrain drag to parent element or fixed bounds\n- disabled?: boolean — Disable dragging\n- grid?: number — Snap to grid interval in pixels\n- children: node — Content to make draggable\nTypes the props use:\n- DragBounds = { top: number; right: number; bottom: number; left: number }\n- DragPosition = { x: number; y: number }\nEvents (write @name={…}; the prop is onName):\n- @dragStart(pos: DragPosition) — Callback when dragging starts\n- @drag(pos: DragPosition) — Callback during dragging\n- @dragEnd(pos: DragPosition) — Callback when dragging ends\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Draggable>…</Draggable>",
 "Drawer": "## Drawer — A panel that slides in from an edge.\nTag: <Drawer> (group: feedback)\nProps (? = optional):\n- open: boolean — Whether the drawer is open\n- children?: node — Drawer content\n- position?: \"left\" | \"right\" | \"top\" | \"bottom\" — Which side the drawer slides from\n- size?: string — Size of the drawer\n- title?: string — Title shown in header\n- ariaLabel?: string — Accessible name for the drawer when it has no `title`\n- showClose?: boolean — Show close button\n- showOverlay?: boolean — Show overlay backdrop\n- closeOnOverlay?: boolean — Close on overlay click\n- closeOnEscape?: boolean — Close on Escape key\nEvents (write @name={…}; the prop is onName):\n- @close — Callback when drawer should close\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Drawer open={true}>…</Drawer>",
 "EmptyFolder": "## EmptyFolder — Preset empty state for an empty folder (helper; not a registered tag).\nNot registered as a tag: it cannot be used in markup.\nProps: none of its own.\nChildren: none (configure it with props).\nEvery component also takes style and className.",
 "EmptyList": "## EmptyList — Preset empty state for an empty list (helper; not a registered tag).\nNot registered as a tag: it cannot be used in markup.\nProps: none of its own.\nChildren: none (configure it with props).\nEvery component also takes style and className.",
 "EmptySearch": "## EmptySearch — Preset empty state for no search results (helper; not a registered tag).\nNot registered as a tag: it cannot be used in markup.\nPreset empty states for common use cases\nProps: none of its own.\nChildren: none (configure it with props).\nEvery component also takes style and className.",
 "EmptyState": "## EmptyState — What to show when there is nothing yet: icon, title, description, action.\nTag: <EmptyState> (group: essentials)\nProps (? = optional):\n- icon?: node — Icon to display\n- iconSize?: number — Icon size\n- iconColor?: string — Icon color\n- title?: string — Title text\n- description?: string — Description text\n- action?: node — Primary action button\n- secondaryAction?: node — Secondary action\n- size?: \"sm\" | \"md\" | \"lg\" — Size variant\n- variant?: \"default\" | \"card\" | \"minimal\" — Variant\n- animated?: boolean — Enable floating animation on icon\n- noEntranceAnimation?: boolean — Disable entrance animation\n- children?: node — Children (additional content)\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <EmptyState>…</EmptyState>",
 "Field": "## Field — A label, hint and error around any control that has none of its own (Slider, Rating, SegmentedControl, a group of checkboxes).\nTag: <Field> (group: essentials)\nProps (? = optional):\n- label?: node — What the control is for\n- hint?: node — A note under the control\n- error?: React.ReactNode | boolean — What is wrong, shown in place of the hint. `true` marks the field without a message\n- required?: boolean — Mark the label as required\n- layout?: \"vertical\" | \"horizontal\" — Label above the control, or beside it\n- labelWidth?: string — Width of the label in the horizontal layout, as CSS\n- disabled?: boolean — Dim the label and notes with the control\n- children?: node — The control\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Field>…</Field>\nFrom the docs (components):\n```xml\n<DescriptionList items={[{ label: \"Customer\", value: order.name }, { label: \"Paid\", value: order.paid }]} columns={2} />\n\n<Field label=\"Volume\" hint=\"Applies to every sound.\" error={volumeError}>\n  <Slider :bind={volume} />\n</Field>\n\n<ButtonGroup ariaLabel=\"Range\">\n  <Button @click={() => range = \"day\"}>Day</Button>\n  <Button @click={() => range = \"week\"}>Week</Button>\n</ButtonGroup>\n\n<CopyButton value={inviteLink} label=\"Copy invite\" />\n\n<Confirm open={asking} title=\"Delete this note?\" message=\"This cannot be undone.\"\n         confirmText=\"Delete\" variant=\"danger\"\n         @confirm={() => remove()} @cancel={() => asking = false} />\n\n<AvatarGroup max={3}>\n  #each (person in people) key={person.id}\n    <Avatar name={person.name} />\n  #end\n</AvatarGroup>\n```",
 "FileChooser": "## FileChooser — Pick files from the device, as a button or a drop zone.\nTag: <FileChooser> (group: controls)\nProps (? = optional):\n- accept?: string — Accepted file types (e.g. \"image/*,.pdf\")\n- multiple?: boolean — Allow multiple file selection\n- directory?: boolean — Allow directory selection\n- label?: string — Button label (default \"Choose File\")\n- variant?: \"button\" | \"dropzone\" — Display variant (default 'button')\n- value?: FileInfo[] | null — The files shown as chosen, when the page keeps them: what `onSelect` handed it, and `[]` once they have been sent, which shows none. Left out, the chooser shows what was last chosen until it is removed.\n- disabled?: boolean — Whether the chooser is turned off: nothing can be chosen, dropped or removed\nTypes the props use:\n- FileInfo = { name: string; size: number; type: string; ref: string }\nEvents (write @name={…}; the prop is onName):\n- @select(files: FileInfo[]) — Called when files are selected, and with what is left when one is removed\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <FileChooser />",
 "Form": "## Form — Groups inputs and submits them together.\nTag: <Form> (group: essentials)\nProps (? = optional):\n- children?: node — Children\nEvents (write @name={…}; the prop is onName):\n- @submit(event) — Submit handler\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Form>…</Form>",
 "GaugeChart": "## GaugeChart — A single value on a dial, with thresholds.\nTag: <GaugeChart> (group: charts)\nProps (? = optional):\n- value: number\n- min?: number\n- max?: number\n- label?: string\n- thresholds?: GaugeThreshold[]\n- variant?: \"semicircle\" | \"arc\" | \"full\"\n- animated?: boolean\n- width?: number\n- height?: number\n- formatValue?: function\n- ariaLabel?: string — Accessible name for the meter; `label`, or \"Gauge\", by default\nTypes the props use:\n- GaugeThreshold = { value: number; color: string }\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <GaugeChart value={1} />",
 "Grid": "## Grid — CSS grid layout: columns, rows and gaps.\nTag: <Grid> (group: essentials)\nProps (? = optional):\n- columns?: number | string | ResponsiveColumns — Number of columns - can be number, string, or responsive object\n- rows?: number | string — Number of rows\n- gap?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Gap between items\n- columnGap?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Column gap\n- rowGap?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Row gap\n- alignItems?: \"start\" | \"center\" | \"end\" | \"stretch\" — Align items\n- justifyItems?: \"start\" | \"center\" | \"end\" | \"stretch\" — Justify items\n- padding?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Padding\n- minColumnWidth?: string — Min column width for auto-fit (enables responsive grid)\n- responsive?: boolean — Enable automatic responsive behavior (1 col on mobile, scales up)\n- collapseOnMobile?: boolean — Collapse to single column on mobile\n- children?: node — Children\nTypes the props use:\n- ResponsiveColumns = { sm?: number; md?: number; lg?: number; xl?: number }\n  - sm: Columns on mobile (< 640px)\n  - md: Columns on tablet (>= 640px)\n  - lg: Columns on desktop (>= 1024px)\n  - xl: Columns on large desktop (>= 1280px)\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Grid>…</Grid>\nFrom the docs (assets-themes-responsive):\n```xml\n<Grid columns={3} gap=\"md\" collapseOnMobile>…</Grid>\n<Grid columns={{ sm: 1, md: 2, lg: 4 }} gap=\"md\">…</Grid>\n<Grid minColumnWidth=\"220px\" gap=\"md\">…</Grid>\n<Stack direction=\"horizontal\" gap=\"md\" mobileVertical>…</Stack>\n```",
 "Header": "## Header — A top bar with a title; can stick to the top.\nTag: <Header> (group: essentials)\nProps (? = optional):\n- children?: node — Header content\n- title?: string — Header title (shorthand)\n- background?: string — Background color\n- borderColor?: string — Border color\n- sticky?: boolean — Sticky header\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Header>…</Header>\nFrom the docs (ui-language):\n```xml\n<import Header from=\"./components/header.ui\" />\n<import TodoItem from \"./components/todo-item.ui\" />\n<logic src=\"./app.logic\" />\n\n<App>\n  <Header />\n  #each (todo in filteredTodos) key={todo.id}\n    <TodoItem />\n  #end\n</App>\n```",
 "Heading": "## Heading — A heading, h1 to h6 (level).\nTag: <Heading> (group: essentials)\nProps (? = optional):\n- level?: 1 | 2 | 3 | 4 | 5 | 6 — Heading level (1-6)\n- content?: string — Text content\n- variant?: \"default\" | \"muted\" | \"primary\" | \"gradient\" — Text color variant\n- color?: string — Custom text color (overrides variant)\n- align?: \"left\" | \"center\" | \"right\" — Text alignment\n- truncate?: boolean — Whether to truncate with ellipsis\n- lineClamp?: number — Maximum number of lines (with ellipsis)\n- transform?: \"none\" | \"uppercase\" | \"lowercase\" | \"capitalize\" — Text transform\n- letterSpacing?: \"tight\" | \"normal\" | \"wide\" — Letter spacing\n- underline?: boolean — Decorative underline\n- children?: node — Children\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Heading>…</Heading>\nFrom the docs (first-app):\n```xml\n<logic src=\"../logic/main.logic\" />\n\n<App theme=\"dark\">\n  <Stack direction=\"vertical\" gap=\"md\" padding=\"lg\">\n    <Heading level={1}>My first SoftN app</Heading>\n    <Text>Count: {count}</Text>\n    <Button variant=\"primary\" @click={increment}>Increment</Button>\n  </Stack>\n</App>\n```",
 "Icon": "## Icon — A named icon from the built-in set, or an SVG.\nTag: <Icon> (group: essentials)\nProps (? = optional):\n- name?: string — Built-in icon name\n- svg?: string — Custom SVG markup (raw SVG string)\n- size?: number | string — Icon size in px (default 20)\n- color?: string — Icon color (default currentColor)\n- ariaLabel?: string — What the icon means, when it is the only thing saying it (an icon-only status, say). Without one the icon is decoration and hidden from assistive technology; the text or button beside it carries the meaning.\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Icon />\nFrom the docs (ui-language):\n```xml\n#each (todo in todos) key={todo.id}\n  <Checkbox :bind={todo.done} label={todo.title} />\n  <Button @click={() => todo.count++}>More</Button>\n#end\n\n#each ({ id, title }, i in tasks) key={id}\n  <Text>{i + 1}. {title}</Text>\n#end\n\n#each ([name, total] in Object.entries(totals))\n  <Text>{name}: {total}</Text>\n#end\n\n#each (star in 5)\n  <Icon name=\"star\" />\n#end\n```",
 "Image": "## Image — An image with fit, position and radius.\nTag: <Image> (group: essentials)\nProps (? = optional):\n- src: string — Image source URL\n- alt: string — Alt text\n- width?: string | number — Image width\n- height?: string | number — Image height\n- objectFit?: \"contain\" | \"cover\" | \"fill\" | \"none\" | \"scale-down\" — Object fit\n- objectPosition?: string — Object position\n- borderRadius?: 'none' | 'sm' | 'md' | 'lg' | 'full' | string — Border radius\n- fallbackSrc?: string — Fallback source on error\n- loading?: \"lazy\" | \"eager\" — Loading strategy\n- showPlaceholder?: boolean — Show loading placeholder\n- placeholderColor?: string — Placeholder color\nEvents (write @name={…}; the prop is onName):\n- @click — Click handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Image src=\"src\" alt=\"alt\" />\nFrom the docs (assets-themes-responsive):\n```xml\n<Image src={asset(\"assets/cover.png\")} alt=\"The book’s cover\" />\n```",
 "Input": "## Input — A single-line text field: text, email, password, number and more.\nTag: <Input> (group: essentials)\nProps (? = optional):\n- type?: \"text\" | \"email\" | \"password\" | \"number\" | \"tel\" | \"url\" | \"search\" | \"date\" | \"time\" | \"datetime-local\" — Input type\n- name?: string — Input name\n- value?: string | number — Current value\n- defaultValue?: string | number — Default value\n- placeholder?: string — Placeholder text\n- label?: string — Label text\n- helperText?: string — Helper text below input\n- disabled?: boolean — Whether the input is disabled\n- readOnly?: boolean — Whether the input is read-only\n- required?: boolean — Whether the input is required\n- size?: \"sm\" | \"md\" | \"lg\" — Input size\n- variant?: \"outline\" | \"filled\" | \"flushed\" — Input variant\n- fullWidth?: boolean — Full width\n- flex?: number | string — Flex\n- error?: boolean | string — Error state or error message\n- success?: boolean — Success state\n- leftElement?: node — Left element (icon or text)\n- rightElement?: node — Right element (icon or text)\n- leftAddon?: node — Left addon (outside the input)\n- rightAddon?: node — Right addon (outside the input)\n- min?: number — Minimum value (for number)\n- max?: number — Maximum value (for number)\n- step?: number — Step (for number)\n- pattern?: string — Pattern for validation\n- autoComplete?: string — Auto complete\n- autoFocus?: boolean — Auto focus\n- clearable?: boolean — Show clear button when input has value (auto-enabled for search)\n- hideSearchIcon?: boolean — Hide the default search icon for type=\"search\"\nEvents (write @name={…}; the prop is onName):\n- @clear — Callback when clear button is clicked\n- @change(event) — Change handler\n- @focus(event) — Focus handler\n- @blur(event) — Blur handler\n- @keyDown(event) — Key down handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Input />\nFrom the docs (state-events):\n```xml\n<Input :bind={username} placeholder=\"Name\" />\n<Button @click={() => save()}>Save</Button>\n```",
 "Kbd": "## Kbd — A keyboard key or shortcut, such as Ctrl+K.\nTag: <Kbd> (group: display)\nProps (? = optional):\n- keys?: string | string[] — The key or combination: \"Enter\", \"Ctrl+K\", or a list of keys\n- separator?: string — Text between the keys of a combination\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- children?: node — A single key, as content\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Kbd>…</Kbd>\nFrom the docs (ui-language):\n```xml\n<Text>Press <Kbd keys=\"Ctrl+S\" /> to save, or <a href=\"/help\">read how</a>.</Text>\n<Text><b>Total:</b> {total} <i>items</i></Text>\n<Input placeholder=\"e.g. &quot;Milk&quot; &amp; eggs\" />\n```",
 "Layout": "## Layout — Page layout frame that holds Header, Sidebar and Content.\nTag: <Layout> (group: essentials)\nProps (? = optional):\n- children?: node — Layout content (sidebar, header, content)\n- direction?: \"horizontal\" | \"vertical\" — Layout direction\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Layout>…</Layout>",
 "LineChart": "## LineChart — Line chart for one or more series.\nTag: <LineChart> (group: charts)\nProps (? = optional):\n- series: LineChartSeries[]\n- width?: number\n- height?: number\n- padding?: Partial<ChartPadding> | number\n- showGrid?: boolean\n- showXAxis?: boolean\n- showYAxis?: boolean\n- showLegend?: boolean\n- xAxisLabel?: string\n- yAxisLabel?: string\n- yMin?: number\n- yMax?: number\n- formatXLabel?: function\n- formatYLabel?: function\n- interactive?: boolean\n- ariaLabel?: string — Text alternative for the chart; a summary of its values by default\nTypes the props use:\n- LineChartSeries = { name: string; data: DataPoint[]; color?: string; strokeWidth?: number; showDots?: boolean; dotSize?: number; fill?: boolean; fillOpacity?: number; smooth?: boolean }\n- ChartPadding = { top: number; right: number; bottom: number; left: number }\n  The space a chart leaves around its plot, a number for each side.\n- DataPoint = { x: number | string; y: number; label?: string }\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <LineChart series={[]} />",
 "List": "## List — A vertical list of ListItem rows.\nTag: <List> (group: essentials)\nProps (? = optional):\n- variant?: \"default\" | \"bordered\" | \"divided\" — List variant\n- spacing?: \"none\" | \"sm\" | \"md\" | \"lg\" — List spacing\n- hoverable?: boolean — Whether items are hoverable\n- ordered?: boolean — Whether list is ordered\n- children?: node — List items\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <List>…</List>",
 "ListItem": "## ListItem — One row of a List, with leading and trailing content.\nTag: <ListItem> (group: essentials)\nProps (? = optional):\n- active?: boolean — Whether item is active\n- disabled?: boolean — Whether item is disabled\n- leading?: node — Leading content (icon, avatar)\n- trailing?: node — Trailing content (action, badge)\n- children?: node — Item content\nEvents (write @name={…}; the prop is onName):\n- @click — Click handler\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <ListItem>…</ListItem>",
 "Loop": "## Loop — A game or animation clock: calls @tick with the seconds since the last call while running. With frame, once a screen frame and not while hidden; else every interval ms.\nTag: <Loop> (group: essentials)\nProps (? = optional):\n- interval?: number — Milliseconds between ticks of the timer form (default 1000). Not read with `frame`, which follows the screen.\n- running?: boolean — Whether the loop is running (default false)\n- frame?: boolean — Tick once for each frame the screen draws (usually 60 a second, more on a fast display) instead of on a timer, and not at all while the app or the browser's tab is hidden. The first tick after it is shown again carries one frame's time, not the time it was away. Write movement as speed times `dt`, since the rate is the screen's: `x += 220 * dt`. On a screen or a page too slow to draw four frames a second, each frame still ticks, with the longest step (`dt` 0.2).\n- maxFps?: number — With `frame`, the most ticks in a second: `maxFps={30}` for logic that is too heavy to run on every frame. Left out, every frame ticks.\n- pauseHidden?: boolean — For the timer form: stop ticking while the app or the browser's tab is hidden, and start again when it is shown (default false, so a timer that keeps time in the background still does). `frame` always stops there.\nEvents (write @name={…}; the prop is onName):\n- @tick(dt?: number) — Called on each tick with `dt`, the seconds since the last one (between 0.001 and 0.2). The next tick waits for this one to finish; with `frame` it waits two seconds at most, then goes on without it and says so once in the console. Do not wait on a request inside the step: start it, and read its result on a later tick.\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Loop />\nFrom the docs (threejs-games):\n```xml\n<Loop frame running={playing} @tick={step} />\n```",
 "MarkdownEditor": "## MarkdownEditor — Edit Markdown with a live preview.\nTag: <MarkdownEditor> (group: editors)\nProps (? = optional):\n- value?: string — Current value\n- defaultValue?: string — Default value\n- placeholder?: string — Placeholder text\n- disabled?: boolean — Whether the editor is disabled\n- readOnly?: boolean — Whether the editor is read-only\n- viewMode?: \"edit\" | \"preview\" | \"split\" — View mode: edit, preview, or split\n- ariaLabel?: string — Accessible name for the text area (default \"Markdown\")\n- showToolbar?: boolean — Show toolbar\n- minHeight?: string — Minimum height\n- maxHeight?: string — Maximum height\nEvents (write @name={…}; the prop is onName):\n- @viewModeChange(mode: 'edit' | 'preview' | 'split') — Called when the user switches view mode\n- @change(value: string) — Change handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <MarkdownEditor />",
 "Marquee": "## Marquee — Scrolls its children continuously.\nTag: <Marquee> (group: animation)\nProps (? = optional):\n- speed?: number — Scroll speed in pixels per second\n- direction?: \"left\" | \"right\" | \"up\" | \"down\" — Scroll direction\n- pauseOnHover?: boolean — Whether to pause the animation on hover\n- gap?: number — Gap between repeated content in pixels\n- children: node — Content to scroll\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Marquee>…</Marquee>",
 "Menu": "## Menu — A dropdown menu of items from a trigger.\nTag: <Menu> (group: navigation)\nProps (? = optional):\n- items: MenuItem[] — Menu items\n- trigger: node — Trigger element\n- placement?: \"bottom-start\" | \"bottom-end\" | \"top-start\" | \"top-end\" — Menu placement\n- width?: string | number — Menu width\n- ariaLabel?: string — Accessible name for the trigger, when its content does not give one (an icon)\nTypes the props use:\n- MenuItem = { key: string; label: string; icon?: string; disabled?: boolean; danger?: boolean; onClick?: () => void; divider?: boolean }\n  - key: Unique key\n  - label: Item label\n  - icon: Icon\n  - disabled: Whether disabled\n  - danger: Danger style\n  - onClick: Click handler\n  - divider: Divider after this item\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Menu items={[]} trigger={trigger} />",
 "Microphone": "## Microphone — Records clips or streams microphone input (needs the mic permission).\nTag: <Microphone> (group: media)\nProps (? = optional):\n- mode?: \"clip\" | \"live\" | \"level\" — What the microphone is for (default 'clip'). - `clip` — record until stopped, then report a WAV in `onCapture` - `live` — report windows of samples continuously in `onSamples` - `level` — report loudness only; the cheapest mode, and the samples never leave the component\n- active?: boolean — Whether the microphone is open (default true)\n- sampleRate?: number — Sample rate to ask the audio system for, in Hz (default 48000). A request, not a promise: hardware and browser both get a say. Every callback reports the rate actually in use, and code that cares about absolute frequencies must read that rather than assume this.\n- frameSize?: number — Samples per `onSamples` callback in live mode (default 2048)\n- processing?: boolean — Browser voice processing — echo cancellation, noise suppression and automatic gain control (default true). On is right for speech: it is what makes a voice note sound like a voice note. Off is right for anything measuring the sound rather than listening to it. All three are trained on speech and treat a steady tone as noise to be removed, so a level meter reads low, a tuner drifts, and data sent over audio arrives as silence. One switch, because they fail together.\n- showControls?: boolean — Whether to show the built-in record button (default true)\n- showMeter?: boolean — Whether to show the built-in level meter (default true)\n- maxSeconds?: number — Stop a clip automatically after this many seconds (default 60)\n- autoStart?: boolean — Start recording as soon as the microphone opens, in clip mode (default false)\n- width?: number | string — Width in pixels, or any CSS width (default '100%')\n- height?: number — Height of the meter strip in pixels (default 64)\n- children?: node — Rendered below the meter\nEvents (write @name={…}; the prop is onName):\n- @capture(data: { dataUrl: string; duration: number; sampleRate: number; sampleCount: number; mimeType: string }) — Called when a clip finishes recording\n- @samples(data: { samples: number[]; sampleRate: number; timestamp: number }) — Called with each window of samples in live mode. `samples` is a plain array, not a Float32Array: everything crossing into the scripting VM is deep-cloned through an allowlist that admits plain objects and arrays and drops everything else, so a typed array would arrive as null.\n- @level(data: { level: number; peak: number; clipping: boolean }) — Called about 20 times a second with the current loudness, 0..1\n- @start — Called when recording starts\n- @stop — Called when recording stops, just before onCapture\n- @error(error: string) — Called when the microphone cannot be opened, or capture fails\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Microphone>…</Microphone>",
 "Modal": "## Modal — A dialog over the page; open with open/isOpen, close with @close.\nTag: <Modal> (group: feedback)\nProps (? = optional):\n- isOpen?: boolean — Whether the modal is open\n- open?: boolean — Alias for isOpen (for softn compatibility)\n- title?: string — Modal title\n- ariaLabel?: string — Accessible name for the dialog when it has no `title`\n- size?: \"sm\" | \"md\" | \"lg\" | \"xl\" | \"full\" — Modal size\n- closeOnOverlayClick?: boolean — Close on overlay click\n- closeOnEscape?: boolean — Close on Escape key\n- showCloseButton?: boolean — Show close button\n- centered?: boolean — Center modal vertically\n- loading?: boolean — Loading state - shows spinner overlay\n- loadingText?: string — Loading text to display\n- preventCloseOnLoading?: boolean — Prevent closing while loading\n- disableAnimation?: boolean — Disable animations\n- overlayColor?: string — Custom overlay color\n- children?: node — Modal content\n- footer?: node — Footer content\n- headerExtra?: node — Header extra content (right side, before close button)\nEvents (write @name={…}; the prop is onName):\n- @close — Callback when modal should close\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Modal>…</Modal>\nFrom the docs (ui-language):\n```xml\n<Button @click={() => adding = true}>New task</Button>\n<Modal :bind={adding} title=\"New task\">…</Modal>\n<Confirm :bind={asking} title=\"Delete this task?\" @confirm={() => remove(task)} />\n<Tabs :bind={tab} tabs={[{ key: \"open\", label: \"Open\" }, { key: \"done\", label: \"Done\" }]} />\n<Pagination :bind={page} totalPages={pages} />\n```",
 "NavItem": "## NavItem — A navigation link or button, marked active for the current page.\nTag: <NavItem> (group: navigation)\nProps (? = optional):\n- label?: string — Item label\n- children?: node — Children (alternative to label)\n- icon?: React.ReactNode | string — Icon name or element\n- page?: string — The page of the app to show, by the name its state holds it under\n- navigate?: string — An address to go to: another page of the app (`about.html`), a `#fragment`, or a web address\n- active?: boolean — Whether this item is active\n- collapsed?: boolean — Collapsed mode - show only icon with tooltip\n- variant?: \"default\" | \"ghost\" | \"primary\" — Variant style\nEvents (write @name={…}; the prop is onName):\n- @click — Click handler\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <NavItem>…</NavItem>",
 "NumberInput": "## NumberInput — A number to type or step with + and −; @change and :bind give a number, or null when empty.\nTag: <NumberInput> (group: controls)\nProps (? = optional):\n- value?: number | string | null — The number\n- defaultValue?: number — Starting number, when the app does not hold it\n- min?: number — Smallest number allowed\n- max?: number — Largest number allowed\n- step?: number — How much one step changes it\n- precision?: number — Decimal places kept; worked out from the step when omitted\n- name?: string — Input name\n- placeholder?: string — Placeholder text\n- disabled?: boolean — Whether the input is disabled\n- readOnly?: boolean — Whether the number can be read but not changed\n- error?: boolean — Error state\n- hideControls?: boolean — Hide the step buttons\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- fullWidth?: boolean — Stretch to the width available\n- ariaLabel?: string — Accessible name, when no visible label names the field\nEvents (write @name={…}; the prop is onName):\n- @change(value: number | null) — Called with the new number, or null when the field is emptied\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <NumberInput />\nFrom the docs (components):\n```xml\n<SegmentedControl :bind={view} options={[\"List\", \"Board\", \"Calendar\"]} />\n<NumberInput :bind={quantity} min={1} max={99} />\n<Rating :bind={score} max={5} />\n<Steps items={[\"Cart\", \"Shipping\", \"Payment\"]} :bind={step} />\n```",
 "Pagination": "## Pagination — Page controls for a long list or table.\nTag: <Pagination> (group: data)\nProps (? = optional):\n- currentPage: number\n- totalPages: number\n- totalItems?: number\n- pageSize?: number\n- pageSizeOptions?: number[]\n- showPageSize?: boolean\n- showTotal?: boolean\n- showFirstLast?: boolean\n- siblingCount?: number\n- size?: \"sm\" | \"md\" | \"lg\"\n- ariaLabel?: string — Accessible name for the navigation landmark\nEvents (write @name={…}; the prop is onName):\n- @pageChange(page: number)\n- @pageSizeChange(size: number)\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Pagination currentPage={1} totalPages={1} />\nFrom the docs (ui-language):\n```xml\n<Button @click={() => adding = true}>New task</Button>\n<Modal :bind={adding} title=\"New task\">…</Modal>\n<Confirm :bind={asking} title=\"Delete this task?\" @confirm={() => remove(task)} />\n<Tabs :bind={tab} tabs={[{ key: \"open\", label: \"Open\" }, { key: \"done\", label: \"Done\" }]} />\n<Pagination :bind={page} totalPages={pages} />\n```",
 "PanView": "## PanView — A draggable, zoomable viewport over large content.\nTag: <PanView> (group: animation)\nProps (? = optional):\n- contentWidth: number — Width of the content, in its own unscaled units.\n- contentHeight: number — Height of the content, in its own unscaled units.\n- scale?: number — Zoom applied to the content. The centre of the view is held still across changes.\n- centered?: boolean — Start scrolled to the middle of the content rather than its top-left corner.\n- recenterKey?: number | string — Change this to scroll back to the middle — for a \"recentre\" control.\n- draggable?: boolean — Set false for content that needs its own drag behaviour (selection, drawing).\n- background?: string — Painted behind the content, and visible in the margin when it is smaller than the view.\n- label?: string — Accessible name for the scrollable region.\n- children?: node\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <PanView contentWidth={1} contentHeight={1}>…</PanView>",
 "PieChart": "## PieChart — Pie or donut chart.\nTag: <PieChart> (group: charts)\nProps (? = optional):\n- data: PieDataPoint[]\n- width?: number\n- height?: number\n- innerRadius?: number\n- showLabels?: boolean\n- showLegend?: boolean\n- showValues?: boolean\n- centerLabel?: string\n- formatValue?: function\n- formatPercent?: function\n- interactive?: boolean\n- ariaLabel?: string — Text alternative for the chart; a summary of its values by default\nTypes the props use:\n- PieDataPoint = { label: string; value: number; color?: string }\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <PieChart data={[]} />",
 "PixelCanvas": "## PixelCanvas — A pixel framebuffer drawn from the logic: emulators, retro games.\nTag: <PixelCanvas> (group: games)\nProps (? = optional):\n- width?: number — Logical width of the bitmap, in pixels. A frame may override it.\n- height?: number — Logical height of the bitmap, in pixels. A frame may override it.\n- scale?: number — Integer upscale factor. Omitted, the canvas fits itself to the width available and takes the largest whole multiple that fits — whole, because a fractional multiple makes some source pixels wider than others and the seams are visible on anything with a grid in it. If not even 1:1 fits, it scales down to fit rather than overflowing. Height is only taken into account when the container has a height of its own (given through `style`). Deriving the scale from a height that is itself derived from the canvas would just measure the canvas.\n- fit?: \"pixel\" | \"contain\" — How the bitmap fills its container when `scale` is not given. `\"pixel\"` (the default) takes the largest whole multiple that fits and centres it. Every source pixel is the same size, which is what pixel art and anything with a grid in it needs — at the cost of leaving a margin, since a 160-wide bitmap in a 405px box is 2x and not 2.53x. `\"contain\"` fills the container instead, keeping the aspect ratio but allowing a fractional factor. The margin goes away; in exchange some source pixels land on three screen pixels and their neighbours on four. With nearest-neighbour scaling that is a faint unevenness in the seams rather than blurring, and on a photographic or continuous-tone bitmap it is invisible. Choose it when filling the frame matters more than exact pixel geometry — a console screen in a bezel, a video, a fullscreen view.\n- palette?: readonly PixelCanvasColor[] — Palette for one-byte-per-pixel frames. Its presence is also what tells the component the frames are indexed: with a palette, a frame is one byte per pixel; without, four. A frame that says `format` explicitly overrides that.\n- getFrame?: function — Called once per `requestAnimationFrame`, returning the next frame — a base64 string of its bytes, or a {@link PixelCanvasFrame} for producers that also need to say how big it is or what palette it uses. Returning `null` or `undefined` means \"no new frame\": the last image stays up and nothing is decoded. A producer slower than the display should do exactly that rather than resending the frame already on screen.\n- frame?: PixelCanvasSource — A frame as a prop, repainted whenever it changes. The alternative to `getFrame`, for sources that push rather than pull. When both are given `getFrame` wins, since a puller and a pusher driving one surface would fight over it.\n- running?: boolean — Whether the frame loop is running (default true).\n- smooth?: boolean — Smooth the upscale instead of keeping pixels square (default false).\n- ariaLabel?: string — Accessible name; given one, the canvas is announced as an image\nTypes the props use:\n- PixelCanvasColor = string | readonly number[]\n  A palette entry: a CSS colour, or `[r, g, b]` / `[r, g, b, a]` 0-255.\n- PixelCanvasSource = string | PixelCanvasFrame | null | undefined\n  What a frame source hands back. A bare base64 string is the whole of it for simple producers; `null`/`undefined` means \"nothing new, keep what is up\".\n- PixelCanvasFrame = { w?: number; h?: number; format?: string; pixels?: string; palette?: string | readonly PixelCanvasColor[]; paletteRev?: number; frame?: number }\n  The rich form a frame source may return, for producers that need to say more than \"here are the bytes\" — a size that changes, a palette that changes, or a frame counter that lets the canvas skip a repaint it does not need. Every field is optional; anything missing falls back to the component's props.\n  - w: Logical width of this frame; overrides the `width` prop when present.\n  - h: Logical height of this frame; overrides the `height` prop when present.\n  - format: `\"p8\"` (one byte per pixel) or `\"rgba\"` (four). Inferred when absent.\n  - pixels: The frame's bytes, base64.\n  - palette: Palette for `p8` frames: base64 RGB triples (3 bytes an entry), or an array of `PixelCanvasColor`. Overrides the `palette` prop for as long as it is supplied.\n  - paletteRev: Bumped by the producer only when `palette` actually changed. The palette is decoded and re-packed only when this changes, so a producer that sends the same palette every frame costs nothing.\n  - frame: Producer's frame counter. When it is unchanged from the previous call the canvas skips the decode and the repaint entirely — a producer that is paced slower than the display gets this for free.\nEvents (write @name={…}; the prop is onName):\n- @fps(fps: number) — Called about once a second with the frames actually painted per second.\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <PixelCanvas />",
 "PixelGrid": "## PixelGrid — A grid of cells for board and tile games.\nTag: <PixelGrid> (group: games)\nProps (? = optional):\n- rows?: number — Number of rows (default 20)\n- cols?: number — Number of columns (default 20)\n- cellSize?: number — Pixel size per cell (default 20), at most: the board fits the width it is given\n- items?: PixelGridItem[] — Cells to render\n- background?: string — Board background color\n- showGrid?: boolean — Show subtle grid lines (default true)\n- gridColor?: string — Grid line color\n- overlay?: string — Centered overlay text\n- overlayStyle?: React.CSSProperties — Style for overlay\nTypes the props use:\n- PixelGridItem = { x: number; y: number; color: string; borderRadius?: string; opacity?: number }\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <PixelGrid />",
 "Popover": "## Popover — Floating content anchored to a trigger, on click or hover.\nTag: <Popover> (group: feedback)\nProps (? = optional):\n- trigger: node — Trigger element\n- children?: node — Popover content\n- placement?: \"top\" | \"bottom\" | \"left\" | \"right\" — Placement of the popover\n- open?: boolean — Whether popover is controlled\n- defaultOpen?: boolean — Default open state\n- triggerMode?: \"click\" | \"hover\" — How to trigger the popover\n- offset?: number — Offset from trigger in pixels\n- showArrow?: boolean — Show arrow\n- closeOnOutsideClick?: boolean — Close when clicking outside\n- ariaLabel?: string — Accessible name for the popup\nEvents (write @name={…}; the prop is onName):\n- @openChange(open: boolean) — Callback when open state changes\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Popover trigger={trigger}>…</Popover>",
 "Progress": "## Progress — A progress bar.\nTag: <Progress> (group: display)\nProps (? = optional):\n- value?: number — Progress value (0-100)\n- max?: number — Maximum value\n- size?: \"xs\" | \"sm\" | \"md\" | \"lg\" | \"xl\" — Size\n- variant?: \"primary\" | \"success\" | \"warning\" | \"danger\" | \"info\" — Color variant\n- color?: string — Custom color (overrides variant)\n- backgroundColor?: string — Background color\n- showLabel?: boolean — Show percentage label\n- labelPosition?: \"inside\" | \"outside\" | \"top\" — Label position\n- formatLabel?: function — Custom label formatter\n- indeterminate?: boolean — Indeterminate (loading) state\n- striped?: boolean — Striped style\n- animated?: boolean — Animated stripes\n- borderRadius?: \"none\" | \"sm\" | \"md\" | \"lg\" | \"full\" — Border radius\n- ariaLabel?: string — Accessible name for the bar (default \"Progress\")\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Progress />",
 "QRCode": "## QRCode — Draws a QR code for a value.\nTag: <QRCode> (group: media)\nProps (? = optional):\n- value: string — The data to encode\n- size?: number — Size of the QR code in pixels (default 256)\n- color?: string — Foreground color (default '#000')\n- bgColor?: string — Background color (default '#fff')\n- errorCorrection?: \"L\" | \"M\" | \"Q\" | \"H\" — Error correction level (default 'M')\n- ariaLabel?: string — Accessible name for the code (default \"QR code\")\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <QRCode value=\"value\" />",
 "QRReader": "## QRReader — Scans QR codes with the camera (needs the camera permission).\nTag: <QRReader> (group: media)\nProps (? = optional):\n- facing?: \"user\" | \"environment\" — Camera facing mode (default 'environment')\n- width?: number — Video width in pixels (default 640)\n- height?: number — Video height in pixels (default 480)\n- active?: boolean — Whether the scanner is active (default true)\nEvents (write @name={…}; the prop is onName):\n- @scan(data: string) — Callback fired when a QR code is detected\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <QRReader />",
 "RadarChart": "## RadarChart — Radar (spider) chart across several axes.\nTag: <RadarChart> (group: charts)\nProps (? = optional):\n- series: RadarChartSeries[]\n- axes: string[]\n- maxValue?: number\n- levels?: number\n- width?: number\n- height?: number\n- showLegend?: boolean\n- interactive?: boolean\n- ariaLabel?: string — Text alternative for the chart; a summary of its values by default\nTypes the props use:\n- RadarChartSeries = { name: string; data: RadarDataPoint[]; color?: string }\n- RadarDataPoint = { axis: string; value: number }\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <RadarChart series={[]} axes={[]} />",
 "Radio": "## Radio — Choose one of several options.\nTag: <Radio> (group: controls)\nProps (? = optional):\n- name: string — Input name (required for grouping)\n- options: (RadioOption | string | number)[] — Available options: { value, label, disabled? }, or a bare string or number, which is its own value and label\n- value?: string | number — Currently selected value; 2 and \"2\" choose the same option\n- defaultValue?: string | number — Default selected value\n- direction?: \"horizontal\" | \"vertical\" — Layout direction\n- disabled?: boolean — Whether the entire group is disabled\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- error?: boolean | string — Error state\n- label?: string — Group label\nTypes the props use:\n- RadioOption = { value: string | number; label: string; disabled?: boolean }\n  - value: Option value, which choosing it hands back: text, or a number such as a record's id\n  - label: Display label\n  - disabled: Whether this option is disabled\nEvents (write @name={…}; the prop is onName):\n- @change(value: string | number, event) — Change handler: the chosen option's own value (a number for a numbered option), then the event\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Radio name=\"name\" options={[]} />",
 "Rating": "## Rating — A score out of a few stars, to read (readOnly) or to set; @change and :bind give the number.\nTag: <Rating> (group: controls)\nProps (? = optional):\n- value?: number | string — The score\n- defaultValue?: number — Starting score, when the app does not hold it\n- max?: number — How many stars\n- readOnly?: boolean — Show the score without letting it be changed\n- disabled?: boolean — Whether the control is disabled\n- allowClear?: boolean — Choosing the current score again clears it to zero\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- character?: string — The character drawn for each star\n- color?: string — Colour of the filled stars\n- ariaLabel?: string — Accessible name for the group\nEvents (write @name={…}; the prop is onName):\n- @change(value: number) — Called with the new score\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Rating />\nFrom the docs (components):\n```xml\n<SegmentedControl :bind={view} options={[\"List\", \"Board\", \"Calendar\"]} />\n<NumberInput :bind={quantity} min={1} max={99} />\n<Rating :bind={score} max={5} />\n<Steps items={[\"Cart\", \"Shipping\", \"Payment\"]} :bind={step} />\n```",
 "RichTextEditor": "## RichTextEditor — Formatted text editing with a toolbar.\nTag: <RichTextEditor> (group: editors)\nProps (? = optional):\n- value?: string — Current HTML value\n- defaultValue?: string — Default HTML value\n- placeholder?: string — Placeholder text\n- ariaLabel?: string — Accessible name for the editable region\n- disabled?: boolean — Whether the editor is disabled\n- readOnly?: boolean — Whether the editor is read-only\n- showToolbar?: boolean — Show toolbar\n- minHeight?: string — Minimum height\n- maxHeight?: string — Maximum height\nEvents (write @name={…}; the prop is onName):\n- @change(html: string) — Change handler (returns HTML)\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <RichTextEditor />",
 "Scene3D": "## Scene3D — A Three.js 3D scene from a list of objects, lights and a camera.\nTag: <Scene3D> (group: scene3d)\nProps (? = optional):\n- width?: number — How wide the scene is, in CSS pixels (default 800). It is never wider than the space it is given: in a narrower place, a phone, it shrinks to fit and keeps the shape `width` and `height` describe.\n- height?: number — How tall the scene is at its full `width`, in CSS pixels (default 600).\n- fill?: boolean — Size the canvas to whatever box it sits in, instead of `width`/`height`, and follow that box as it changes — a game that wants the whole viewport puts the scene in a fixed, inset-0 container and says `fill`.\n- objects?: Scene3DObject[] — What is in the scene: a list of records, each with an `id` and a `type`: a shape ('box', 'sphere', 'cylinder', 'capsule', 'prism', 'plane', 'torus', 'cone', 'ring', 'dodecahedron', 'icosahedron', 'octahedron'), or 'model', 'instanced', 'group' or 'particles'. An object whose id is still in the list is changed in place; one whose id has gone is removed. Every object takes `position` and `rotation` (`{ x, y, z }`, rotation in radians, applied in `rotationOrder`, 'XYZ' unless given), `scale`, `color`, `opacity`, `castShadow`, `receiveShadow`, `cursor` or `interactive` (the pointer shown over it), `pickable` (false lets a click through to what is behind; particles are picked only when it is true) and `animate` (`{ rotateY, floatAmplitude }`: a turn and a bob the scene keeps up by itself). In place of working out a rotation, `lookAt` (`{ x, y, z }`: a point the object's front, its +z, faces) or `align` (`{ x, y, z }`: a direction its long axis, its +y, lies along). `transition` (milliseconds) eases this object's changes in place of the scene's `transition`. A shape takes `width`, `height`, `depth` or `radius`, and `texture` (a painted one, by name) or `textureUrl`. A model takes `modelUrl` (a URL, or a path in the app's own bundle such as \"assets/robot.glb\"), `fit` (scale it so its longest side is that many units, standing on the ground), `animation` (`{ clip, loop, progress }`: `progress` from 0 to 1 holds the clip at that point, `time` holds it at that many seconds, and `clip: \"*\"` is every clip of the model at once), `lights` (the lights that are in the model's file: `false` for none of them, `{ intensity }` to dim them, `{ castShadow: true }` for shadows from its sun), `appearance` and `parts` (`{ Wheel_FL: { rotation: { x, y, z } }, Hatch: { visible: false } }`: a named node of the model turned, moved, scaled or hidden, measured from the pose its file gives it; rotation in radians about the part's own axes). An 'instanced' object takes `shape`, `instances` (a flat array, x, y, z a copy, and a `palette` index after them when `palette` is given) and, beside it, `instanceRotations` (one turn about the upright axis a copy, or three angles a copy) and `instanceScales` (one size a copy, or three). A group takes `children`, placed relative to it: a child may be of any type, a model included. A 'particles' cloud takes `particlePositions` (a flat array, x, y, z a particle), `particleSize` and `particleShape` ('square', the default; 'round', a disc with a clean edge; 'soft', a disc that fades out at its edge, for dust, smoke and sparks: these two are drawn see-through, after everything solid).\n- staticObjects?: Scene3DObject[] — Scenery that does not change between frames, kept apart from `objects`. The two are concatenated here, so this is purely about what crosses into the component each frame. A scene's static geometry is usually most of its bytes and almost none of its motion; passing it through `objects` means a host that mirrors state rebuilds all of it every tick to move a few characters. Passed here it is rebuilt only when it actually changes.\n- lights?: Scene3DLight[] — The scene's lights, each `{ type, color, intensity, position, castShadow }` with `type` one of 'ambient', 'directional', 'point', 'spot' or 'hemisphere'. A directional light with `follow: 'camera'` goes with the camera, so its shadows cover the ground around the camera wherever that is; with `follow: 'view'` the box of its shadows is moved forward to cover what is in the picture (its middle `0.8 * shadowCameraSize` ahead of the camera). `shadowNormalBias` (scene units, none by default) takes the dark banding off smooth ground that a low light grazes. Left out altogether, the scene is lit so that what is in it can be seen: a soft ambient light and one sun, which casts shadows when `shadows` is on (not with an `environment`, 'studio' or a panorama, which lights the scene itself). An empty list, `lights={[]}`, is a scene with no light in it, and so is `lights={null}`: only leaving `lights` out asks for the two. A light's `castShadow`, `shadowMapSize`, `shadowBias`, `shadowNear` and `shadowFar`, and a directional light's `shadowCameraSize`, may change at any time.\n- camera?: Scene3DCamera — The camera: `{ position, lookAt, fov, near, far, type, size, follow }`. `position` and `lookAt` are `{ x, y, z }`; `fov` is in degrees (60); `near` and `far` are the nearest and farthest it draws (0.1 and 1000). `type: 'orthographic'` is a camera with no perspective, for a plan or a board seen square on, showing `size` scene units from top to bottom (10). `follow: { target, distance, height, lookAhead }` keeps the camera `distance` behind and `height` above the object whose id is `target`, looking `lookAhead` in front of it, worked out on every frame from where the object is drawn: a chase camera with no arithmetic in the app. `from: \"film\"` looks through a camera that is in the model with that id (a scene exported from Blender has its cameras in it): the view is that camera on every frame, with its lens, and `name` says which of the model's cameras; left out, it is the one the file's own cuts name for the second its clip stands at. Each field may change at any time; one left out leaves the camera as it is.\n- transition?: number — Ease what changes instead of jumping to it, over this many milliseconds (default 0: off). When an object's `position`, `rotation` (or `lookAt`, `align`), `scale`, `color`, `opacity`, `emissive` or `emissiveIntensity` changes, the scene takes it there at a steady rate from where it is drawn now. A game that moves things thirty times a second draws them moving at the screen's rate with `transition={40}`; a figure that follows data glides with 400. An object's own `transition` is used in place of this one. Not eased: an object as it first appears, a move further than `jumpDistance`, anything while the app is hidden, the copies of an 'instanced' object (the object as a whole is), an object whose painted `texture` changes colour, and the height or the turn that `animate` is already moving. A turn goes the short way round.\n- jumpDistance?: number — How far is too far to ease, in scene units (default 4): a move longer than this in one update is a jump, for an object under `transition` and for a camera under `cameraSmoothing`, so a thing that is put somewhere else does not sweep across the view. 0 is no limit: everything is eased however far it goes.\n- background?: string\n- sky?: 'day' | 'sunset' | 'night' | 'dusk' | 'overcast' | 'dawn' | { top: string; bottom: string; middle?: string } — Procedural atmospheric sky gradient: 'day' | 'sunset' | 'night' | 'dusk' | 'overcast' | 'dawn' | { top: string; bottom: string; middle?: string }.\n- grid?: boolean | { size?: number; divisions?: number; color?: string; centerColor?: string; position?: { x: number; y: number; z: number } } — Ground / level editor helper grid. May be turned on, off or changed at any time.\n- crosshair?: boolean — Whether to show a first-person aiming crosshair (defaults to true when pointerLock is active).\n- gameControls?: boolean — The scene keeps a record of which of W A S D, the arrows, Space and Shift are held, for logic to read as `softn.input.keys` or `softn.input.down(\"w\")` (the same record as `window.__softnKeys`). These keys are fixed and touch cannot press them: for keys of your own choosing, a gamepad and an on-screen pad as one record, use `<Controls>`.\n- alpha?: boolean — A see-through canvas, with the page behind showing where nothing is drawn. Read when the scene is made: the drawing context cannot change it afterwards, so a change needs a new scene (an `if=` around it).\n- antialias?: boolean — Smooth edges (default true). Read when the scene is made: the drawing context cannot change it afterwards, so a change needs a new scene (an `if=` around it).\n- shadows?: boolean — Draw shadows: from lights with `castShadow`, by objects with `castShadow`, on objects with `receiveShadow`. May be turned on or off at any time, as a graphics setting is.\n- fog?: { color: string; near: number; far: number }\n- orbitControls?: boolean — Let the person turn the view by dragging, zoom with the wheel and pan, around `camera.lookAt`. May be turned on or off at any time: off, the camera stays where it was left. Ignored while `mouseLook` or `pointerLock` is on. `orbit` limits how far the person can take it, and `onCameraChange` says where they left it.\n- orbit?: Scene3DOrbit — Limits on `orbitControls`: `{ minDistance, maxDistance, minPolar, maxPolar, pan, zoom }`. `minDistance` and `maxDistance` are how near and how far the camera may be from what it orbits, in scene units; `minPolar` and `maxPolar` how high and how low it may go, as angles from straight above in radians (`maxPolar: 1.5708` stops it at the ground); `pan: false` and `zoom: false` switch those off. May change at any time. With an orthographic camera the distances limit nothing: it is zoomed by its size.\n- autoRotate?: boolean\n- autoRotateSpeed?: number\n- expandable?: boolean\n- mouseLook?: boolean — Drag on the scene to look around from where the camera stands. May be turned on or off at any time; turned on, the view starts out facing `camera.lookAt`.\n- mouseLookSensitivity?: number — How far the view turns for each pixel the mouse moves, in radians (default 0.003). May change at any time.\n- pointerLock?: boolean — First-person mouse capture. A click on the canvas locks the pointer (the browser's Escape releases it); while locked, moving the mouse turns the camera and every button press is reported through `onClick` with what the centre of the screen is pointing at. Implies `mouseLook`. May be turned on or off at any time; turned off, a pointer it holds is given back.\n- pitchLimit?: number — How far the view may tilt, in radians (default 0.8 — about 45°). May change at any time.\n- cameraSmoothing?: number — Ease the camera toward each new `camera.position` instead of jumping to it, 0..1 per frame (0 = off). A game that moves its player thirty times a second reads as sixty when the render loop closes the gap between ticks; 0.35 keeps under a frame of lag. A new `camera.lookAt` is eased the same way, so the view turns to it and does not snap, and so is a camera that follows (`camera.follow`). A move further than `jumpDistance` is not eased, nor is anything while the person steers with orbit controls: the camera is theirs then.\n- maxPixelRatio?: number — The most device pixels drawn per CSS pixel (default 2). A full-viewport game on a high-density screen pays four times the fill rate at 2; 1 or 1.25 keeps it fast with little visible cost. May change at any time, as a graphics setting does.\n- toneMapping?: \"aces\" | \"agx\" | \"linear\" | \"reinhard\" | \"cineon\" | \"none\" — Tone mapping curve for cinematic highlights. Defaults to 'aces'.\n- environment?: 'none' | 'studio' | Scene3DEnvironment — Light from the scene's surroundings: 'none' (the default), 'studio', or a panorama of the app's own, `{ url, background, rotation, blur, backgroundIntensity, format }`. 'studio' is a room worked out on the GPU: no download but a small chunk, fetched the first time a scene asks for it. A panorama is a picture of everything around one point, twice as wide as it is tall: it lights the scene, and it is what metal and glossy things reflect. `url` is a Radiance `.hdr` or an OpenEXR `.exr` (real light values, which is what looks right) or a `.jpg`, `.png` or `.webp` (an ordinary picture, fainter and flatter light); a path with no scheme (`\"assets/sky.hdr\"`) is a file in the app's own bundle, as `modelUrl` is. `format` ('hdr', 'exr' or 'image') says the kind where the address's ending does not. `background: true` also shows the panorama behind everything (default false: the scene's `background` or `sky` stands), `blur` from 0 (sharp, the default) to 1 softens what is shown, and `backgroundIntensity` is how bright it is shown (default 1). `rotation` turns the panorama about the upright axis, in radians (default 0): lighting, reflections and background together. Every field may change at any time; another `url` is shown once it has loaded, the last one staying until then. A file that cannot be loaded is warned of once in the console and leaves the scene as it was; so is an `.hdr` or `.exr` larger than 8192 by 4096, or than the device can draw, or one that is not the picture its own header declares. With an orthographic camera the panorama lights the scene just the same but is not shown behind it (a view with no perspective has no panorama): the scene's `background` or `sky` stands. A scene with any environment but 'none' and no `lights` is lit by the environment alone.\n- environmentIntensity?: number — How strongly the environment lights the scene, 'studio' or a panorama alike: a multiple from 0 to 4 (default 0.7).\n- toneMappingExposure?: number — Exposure multiplier for tone mapping (default 1.0).\n- effects?: Scene3DEffects — Post-processing: `{ bloom, vignette, grain, depthOfField, ambientOcclusion }`, each left out for none. `bloom` (true, or `{ strength, radius, threshold }`, defaults 0.45, 0.4 and 0.85) makes bright and emissive things glow; `vignette` darkens the corners (0 to 1); `grain` adds film noise (0 to 1). `depthOfField` blurs what is nearer or further than one distance, as a lens does: `{ focusOn: \"rover\", aperture: 0.02, maxBlur: 0.012 }` keeps the object with that id sharp (a top-level object, a group's child or a model; the distance is worked out on every frame, so it stays sharp as the camera or the object moves, and while no object has that id nothing is blurred), and `{ focus: 4.5, aperture, maxBlur }` keeps a distance sharp, in scene units straight ahead of the camera. `aperture` is how quickly things go soft away from that distance (default 0.02; 0.002 keeps nearly everything sharp, 0.05 leaves a thin slice sharp); `maxBlur` is the most anything is blurred, as a fraction of the picture's width (default 0.012; 0.005 is gentle, 0.02 heavy). An orthographic camera is focused the same way, by distance from the camera. In place of `aperture` and `maxBlur`, `fstop` blurs as a lens of that f-number does: `{ focusOn: \"rover\", fstop: 2.8 }` (1.4 is wide open, 8 nearly all sharp; `sensorHeight` is the sensor's height in millimetres, 24 unless given). A lens's blur grows fast either side of the sharp distance and levels off far beyond it, and is more with a narrow field of view and a near subject; it needs a camera with perspective. `depthOfField: \"camera\"` is the focus of the model's camera the scene looks through (`camera={{ from }}`), as a file exported from Blender records it: the thing it is focused on, or the distance, and its f-number; a camera with no focus recorded blurs nothing. What is in focus keeps the detail on its surfaces; its outline against something far out of focus is softened by a few pixels, since the blur gathers what is around each pixel. See-through things and particles take the blur of what is behind them. It fills the whole picture: with `alpha`, the page no longer shows through. `ambientOcclusion` (true, or `{ radius, intensity }`) darkens softly where surfaces meet: a wheel on the ground, a bracket on a panel. `radius` is how far the darkening reaches, in scene units (default 0.5; it has faded out about half that far from the crease); `intensity` is how dark it is, from 0 to 3 (default 1, which takes about a fifth of the light from a crease; 2 takes about a third). It is the costly one: the scene's solid things are drawn a second time, and every pixel of the picture is then gone over twice, sixteen readings each time, a few times what bloom costs. On a fast desktop graphics card that is a millisecond or so a frame at 1600 by 900; a laptop's built-in graphics or a phone is many times slower, so there keep it for close views, or lower `maxPixelRatio`. See-through things and particles are left out of where the darkening is worked out, so they cast none and none is worked out on them; but it is laid over the finished picture, so glass or a particle in front of a crease is darkened where the crease behind it is. Any effect switches the frame to a chain of passes with tone mapping applied at the end; its edges are smoothed when `antialias` is on, as they are without effects. Each effect's numbers may change at any time without the chain being made again.\n- children?: node — `<SceneAnchor>` tags: page content pinned to places in the scene (a name over a figure, a card beside a part). Anything else written inside a `<Scene3D>` is not shown.\nTypes the props use:\n- Scene3DObject = {\n    appearance?: ModelAppearance — Named morph weights, material colours and mesh visibility for imported assets.\n    id: string\n    type: Scene3DShape | 'model' | 'instanced' | 'group' | 'particles'\n    modelUrl?: string — For `type: 'model'`: where the model is. A path with no scheme (`\"assets/robot.glb\"`) names a file in the app's own bundle, so logic can name a model without `asset()`; a path the bundle does not have is fetched as written. A model can also be a child of a group.\n    modelFormat?: ModelFormat\n    fit?: number — For `type: 'model'`: scale the model so its longest side is this many units, centred on the object's position and standing on its ground (lowest point at y = 0 before `position`). `scale` then multiplies it. The \"loaded\" state of `onModelState` gives the size the file had.\n    reload?: number — For `type: 'model'`: change this number to fetch the same URL again — after a failure, or when the file behind the URL has changed. Each change is a new attempt, reported through `onModelState`; the URL itself changing starts the count over.\n    parts?: Record<string, Scene3DPart> — For `type: 'model'`: move the named parts of the model, each by the name its node has in the file (the \"loaded\" state of `onModelState` lists them as `nodes`): `{ Wheel_FL: { rotation: { x: 1.2, y: 0, z: 0 } }, Hatch: { visible: false }, Arm: { position: { x: 0, y: 0.2, z: 0 }, scale: 1.1 } }`. `rotation` is a turn on top of the pose the file gives the part, about the part's own x, y and z, in radians, applied in that order: `{ x: a }` rolls a wheel about its own axle whichever way the wheel was modelled. `position` is how far the part is moved from where the file puts it, in the units and directions of what it hangs from in the file. `scale` (a number, or `{ x, y, z }`) multiplies the size the file gives it. `visible` shows or hides the part and everything that hangs from it, and has the last word over `appearance.hiddenMeshes`. A part left out, or a field left out of one, is as the file has it (default: none are moved). Names are as the file is loaded, which writes them its own way: a space becomes an underscore and `.`, `:`, `/`, `[` and `]` are dropped, so \"Wheel.FL\" in Blender is \"WheelFL\" here, and either spelling finds it. Where two nodes have one name the first is the one moved. The model's own top node is not a part: it is the object, moved by `position`, `rotation` and `scale`. A name the model has no node for is warned of once in the console. With an `animation` playing, the clip plays and `parts` is applied after it on every frame: where a part is given a rotation, a position or a scale, that replaces what the clip gives the same part, and the clip keeps whatever the part is not given. With a `transition` (the scene's or the object's) a part's rotation, position and scale are eased to each new value, a rotation the short way round, however far it goes; `visible` changes at once.\n    lights?: false | Scene3DModelLights — For `type: 'model'`: the lights that are in the model's file (a scene exported from Blender has its sun and its lamps in it; the \"loaded\" state lists them as `lights`). Left out, they shine as the file has them. `false` switches them all off. `{ intensity: 0.5 }` is each at that multiple of its own strength (1 / 683 turns a Blender export in its \"Standard\" units into plain numbers). `{ castShadow: true }` lets the model's directional and spot lights cast shadows, with the scene's `shadows` on; with it `shadowMapSize` (pixels; 1024 for a directional light, 512 for a spot), `shadowCameraSize` (a directional light's shadows cover a box this many units each way, 15 unless given, kept about what the camera sees wherever the light is in the model), `shadowBias` and `shadowNormalBias` are as a scene light's. A lamp that shines every way (a point light) casts none. A light of a model moves with the model and with its clip. May change at any time.\n    shape?: Scene3DShape — For `type: 'instanced'`: one mesh, drawn once, standing in for thousands of copies of `shape` — a voxel world, a forest, a crowd of the same crate. `instances` is flat: x, y, z and a palette index per copy (stride 4) when `palette` is given, x, y, z (stride 3) when every copy is `color`. A flat number array is the cheapest thing that crosses the scripting boundary.\n    instances?: number[]\n    palette?: string[]\n    instanceRotations?: number[] — For `type: 'instanced'`: how each copy is turned, as a flat array beside `instances`. One number a copy is a turn about the upright (y) axis, in radians: a fence rail running north or east, a walker's heading. Three numbers a copy are its turns about x, y and z. Which it is goes by the length: three times the number of copies (or more) is three each, anything shorter is one each. A copy the array does not reach is not turned.\n    instanceScales?: number[] — For `type: 'instanced'`: how big each copy is, as a flat array beside `instances`. One number a copy is its size in every direction (1 is the shape's own size): grass at each stage of growth in one batch. Three numbers a copy are its sizes along x, y and z. Which it is goes by the length, as for `instanceRotations`.\n    children?: Scene3DObject[] — For `type: 'group'`: a composite object made of child objects. All child positions, rotations, and scales are local to the parent group. Moving or rotating the group moves all children together without clipping or trig.\n    particlePositions?: number[] — For `type: 'particles'`: high-performance particle system using THREE.Points. Flat array of x, y, z positions.\n    particleColors?: number[]\n    particleSize?: number\n    particleShape?: ParticleShape — For `type: 'particles'`: what each particle is drawn as. 'square' (the default) is a hard square, as particles always were; 'round' is a disc with a clean edge; 'soft' is a disc that fades to nothing at its edge: dust, smoke, sparks. A round or a soft cloud is drawn see-through: after everything solid, so it is never painted over by a solid thing behind it, and among other see-through things in order of how far its middle is. Its particles write no depth and are not sorted by distance among themselves, so where two of one cloud overlap, the one listed later is on top. Each is solid at its middle unless `opacity` says less (default 1 for these two shapes). May change at any time.\n    cursor?: string — Custom cursor when hovering over this object (e.g. 'pointer', 'grab'). Any type of object, top-level or a group's child.\n    interactive?: boolean — If true, hover sets cursor to pointer. Any type of object, top-level or a group's child.\n    pickable?: boolean — Whether a click or a hover can land on this object. Set false to let the pointer through to what is behind it: a ground plane, a glass wall, a marker. False on a group leaves out everything in it. Particles are the other way about: they are not picked unless this is true, and then at the size the points are drawn.\n    attach?: 'camera' — `'camera'` pins the object to the camera: `position` becomes an offset in camera space (x right, y up, z forward is negative) and `rotation` a local turn — a first-person weapon, a held block, a helmet edge. It is moved by the render loop every frame, so it never lags the view, and it is left out of the centre-ray picking a pointer-locked scene reports.\n    position?: { x: number; y: number; z: number }\n    rotation?: { x: number; y: number; z: number } — The object's turn about x, y and z, in radians, applied in `rotationOrder`.\n    rotationOrder?: 'XYZ' | 'YXZ' | 'ZXY' | 'ZYX' | 'YZX' | 'XZY' — The order `rotation`'s three angles are applied in: 'XYZ' (the default), 'YXZ', 'ZXY', 'ZYX', 'YZX' or 'XZY'. 'YXZ' is the one for a figure that turns to a heading (y) and then leans or nods (x): in 'XYZ' the lean tips the heading with it.\n    lookAt?: { x: number; y: number; z: number } — Turn the object so its front faces this point, `{ x, y, z }`, keeping it as upright as that allows: a turret at its target, a sign at the player. The front is the object's +z, as it is for a model made facing forward. The point is in the same space as `position`: the scene, or the group for a group's child. `rotation`, when also given, is then a turn of the object's own applied first: the quarter turn a model needs whose front is not its +z.\n    align?: { x: number; y: number; z: number } — Lay the object's long axis along this direction, `{ x, y, z }` (any length): the long axis is the object's +y, the one a cylinder, a capsule or a cone stands along. An arm from shoulder to hand, a beam between two posts, an arrow in flight. `rotation`, when also given, is applied first, so its `y` rolls the object about that axis. `lookAt` is used if both are given.\n    scale?: { x: number; y: number; z: number } | number\n    transition?: number — Take this object to a new `position`, `rotation` (or `lookAt`, `align`), `scale`, `color`, `opacity`, `emissive` or `emissiveIntensity` over this many milliseconds instead of at once, in place of the scene's `transition`; 0 makes this object jump whatever the scene says. A group's `transition` is its children's too, unless a child gives its own.\n    color?: string\n    emissive?: string\n    emissiveIntensity?: number\n    opacity?: number — How solid the object is, from 0 (not seen) to 1 (solid, the default). Anything below 1 is drawn see-through. A cloud of particles is solid too unless it gives one below 1.\n    metalness?: number\n    roughness?: number\n    wireframe?: boolean\n    flatShading?: boolean — Low-poly faceted shading for stylized diorama / retro aesthetics.\n    texture?: string — Procedural texture preset: 'stone' | 'brick' | 'tile' | 'wood' | 'grass' | 'checker' | 'stripes' | 'dots' | 'metal' | 'sand' | 'grid' | 'noise' | 'concrete' | 'rust', and the cut-out decals 'bullethole' | 'blood' | 'scorch' (transparent outside the mark; put them on a plane a few millimetres in front of a surface).\n    textureRepeat?: { x: number; y: number } — Texture tiling repeat across the surface, e.g. { x: 2, y: 2 }.\n    textureUrl?: string — Image texture URL. A path with no scheme (`\"assets/crate.png\"`) names a file in the app's own bundle, so logic can name one without `asset()`; a path the bundle does not have is fetched as written.\n    bumpScale?: number — How deep a texture's relief looks (default 0.03). May change at any time.\n    alphaTest?: number — Cut-out threshold for a texture with transparent pixels (a decal). May change at any time.\n    doubleSided?: boolean — Draw both faces: a flat leaf or a decal seen from behind. May change at any time.\n    fog?: boolean — Set false to keep the object out of the fog: a star field, a moon. May change at any time.\n    castShadow?: boolean — Whether the object casts a shadow (with the scene's `shadows` on, from a light with `castShadow`). A group's is what its children have, unless a child says otherwise for itself.\n    receiveShadow?: boolean — Whether shadows fall on the object. A group's is its children's, unless a child says otherwise for itself.\n    width?: number\n    height?: number\n    depth?: number\n    radius?: number\n    tube?: number — Torus tube thickness. Defaults to 40% of `radius` so small rings stay rings.\n    animate?: { rotateX?: number; rotateY?: number; rotateZ?: number; floatAmplitude?: number; floatSpeed?: number } — Motion the scene keeps up by itself, with no tick from logic: a turn of `rotateX`/`rotateY`/`rotateZ` radians per frame at 60 frames a second (0.01 is a slow spin), and a bob of `floatAmplitude` units up and down around `position.y`, `floatSpeed` radians of the wave per second (default 1). Works on a top-level object and on a group's child.\n    animation?: { clip?: string; playing?: boolean; loop?: 'once' | 'repeat'; speed?: number; crossFadeMs?: number; clampWhenFinished?: boolean; progress?: number; time?: number } — For `type: 'model'`: which of the model's clips plays (the \"loaded\" state of `onModelState` lists their names, and how long each is; the first when none is named), and how. `clip: \"*\"` is every clip of the model at once, on one clock: a scene whose camera, figures and machines were each animated as a clip of their own plays as it was made. Each clip of the set that is shorter than the longest holds its last pose until the longest ends, and with `loop: 'repeat'` (the default) they all start again together; `\"*\"` is not cross-faded to or from. (A clip whose own name is `*` cannot be played alone by that name: `\"*\"` is always all of them.)\n  }\n- Scene3DLight = {\n    id?: string\n    type: 'ambient' | 'directional' | 'point' | 'spot' | 'hemisphere'\n    color?: string\n    groundColor?: string\n    intensity?: number\n    position?: { x: number; y: number; z: number }\n    castShadow?: boolean — Whether the light casts shadows (directional, point and spot lights; the scene's `shadows` must be on). May be turned on or off at any time, and so may `shadowMapSize`, `shadowBias`, `shadowNear` and `shadowFar`, and a directional light's `shadowCameraSize`.\n    follow?: 'camera' | 'view' — For a directional light: `'camera'` carries the light with the camera, keeping its direction (`position` is then where it stands from the camera, and so which way it shines). Its shadows cover the ground around the camera wherever the camera goes, where a light that stays put shadows only `shadowCameraSize` units around the middle of the world. `'view'` does the same with the box of its shadows moved forward, its middle `0.8 * shadowCameraSize` ahead of the camera along its line of sight: a box about the camera has half of itself behind the camera, and this one covers what is in the picture with the same map. The default is neither: the light stays where `position` puts it.\n    angle?: number — Spot cone half-angle in radians (default 0.5), and how soft its edge is, 0..1.\n    penumbra?: number\n    distance?: number — Point and spot: how far the light reaches (0 = no limit) and how fast it falls off.\n    decay?: number\n    shadowMapSize?: number — Shadow map resolution in pixels (e.g. 1024 or 2048). Defaults to 1024 for a directional light, 512 for a point or spot light.\n    shadowCameraSize?: number — A directional light's shadows cover a box this many units each way from where the light aims (default 15). Larger covers more ground with coarser shadows at the same `shadowMapSize`.\n    shadowBias?: number — Shadow bias to avoid self-shadowing acne (default -0.0005 for a directional light, none for a point or spot light).\n    shadowNormalBias?: number — How far off a surface, along the way it faces, the place a shadow is looked up for is moved, in scene units (default 0: not moved). For a light that grazes smooth-shaded ground made of large faces: each face that turns a little away from the light, while its smoothed shading still faces it, shadows itself, and thin dark streaks run along the lines between faces. A few hundredths of a unit takes them away, where `shadowBias` large enough to do it would lift every shadow off the foot of what casts it. Too much thins the shadows of thin things. May change at any time.\n    shadowNear?: number — How near to the light and how far from it shadows are drawn: from 0.5 to 150 for a directional light, from 0.5 to 500 for a point or spot light (which, given a `distance`, draws them that far). A point or spot light's nearest must be above zero.\n    shadowFar?: number\n    attach?: 'camera' — `'camera'` carries the light with the view: `position` is an offset in camera space, and a spot light points where the camera points — a torch in the player's hand, a miner's lamp on a helmet.\n  }\n- Scene3DCamera = { position?: { x: number; y: number; z: number }; lookAt?: { x: number; y: number; z: number }; fov?: number; near?: number; far?: number; type?: 'perspective' | 'orthographic'; size?: number; follow?: Scene3DFollow; from?: string; name?: string }\n  - position: Where the camera stands, `{ x, y, z }` (at first `{ x: 0, y: 3, z: 8 }`).\n  - lookAt: The point the camera looks at, `{ x, y, z }` (at first the middle of the scene).\n  - fov: A perspective camera's field of view from top to bottom, in degrees (at first 60).\n  - near: The nearest the camera draws, in scene units from itself (at first 0.1). Nothing nearer is shown.\n  - far: The farthest the camera draws (at first 1000). A large world needs more; a small one is sharper with less.\n  - type: 'perspective' (the default: far things are smaller) or 'orthographic' (they are not: a plan, an elevation, a board seen square on). May change at any time; the camera stays where it is.\n  - size: For `type: 'orthographic'`: how much of the scene is in view from top to bottom, in scene units (at first 10).\n  - follow: Keep the camera behind an object: `{ target, distance, height, lookAhead }`. It stands `distance` behind the object named by `target` (behind is away from the object's front, its +z, turned as the object is turned) and `height` above it, and looks at the point `lookAhead` in front of it. Worked out on every frame from where the object is drawn, so it follows an object that `transition` is easing without shaking, and is eased itself by `cameraSmoothing`. While no object has that id the camera is `position` and `lookAt`. Not used while `mouseLook` or `pointerLock` is on; orbit controls wait while it follows.\n  - from: Look through a camera that is in a model: the `id` of a `type: 'model'` object (top-level, or a group's child) whose file has cameras in it, as a scene exported from Blender has. While that model is loaded and has the camera, the scene's view is that camera on every frame: where it stands and which way it faces as the model is drawn (after its clip and its `parts`), its vertical field of view, and its nearest and farthest unless `near` and `far` are given here (the file's are lengths of the model, so a model drawn at a hundredth of its size has them a hundredth as long; `near` and `far` given here are in the scene's units and are used as they are; a camera whose file gives it no farthest keeps the scene's). A cut from one camera to another is never eased: one frame is the old camera's, the next the new one's. A scene narrower than the picture the camera was made for widens the view up and down so the sides of that picture are kept; a wider one keeps it and shows more at the sides. Until the model has loaded, and for a model with no camera, the view is `position` and `lookAt` as it always was. While a model's camera is in force, `follow`, `cameraSmoothing`, `mouseLook` and orbit controls do nothing. When `from` goes (or its model does), the scene's own camera is back at once where it would have been: at `position` and looking at `lookAt` where those are given, and otherwise where it stood before (where the person had orbited it to, say).\n  - name: With `from`: the name of the camera to look through (the model's \"loaded\" state lists them as `cameras`). Left out, it is the camera the file's own cuts name for the second the film stands at (a film cuts from camera to camera by itself), and for a file with no cuts the model's first camera, whether or not that one has a name. A camera with no name cannot be asked for by one, and is not in the list.\n- Scene3DOrbit = { minDistance?: number; maxDistance?: number; minPolar?: number; maxPolar?: number; pan?: boolean; zoom?: boolean }\n  How far the person may take the camera with `orbitControls`. Each limit left out is not a limit.\n  - minDistance: The nearest the camera may come to what it orbits, in scene units: it cannot be zoomed through an object.\n  - maxDistance: The farthest it may go.\n  - minPolar: The highest the camera may go, as an angle from straight above, in radians (0 is straight above).\n  - maxPolar: The lowest it may go: `Math.PI / 2` (1.5708) stops it at the ground, so it cannot orbit under the floor.\n  - pan: Set false so the person cannot slide the view sideways (pan).\n  - zoom: Set false so the person cannot zoom.\n- Scene3DEnvironment = { url: string; format?: EnvironmentFormat; background?: boolean; rotation?: number; blur?: number; backgroundIntensity?: number }\n  A panorama the scene is lit by, as `environment` takes one.\n  - url: Where the panorama is: a picture of everything around one point, twice as wide as it is tall (equirectangular). A path with no scheme (`\"assets/sky.hdr\"`) names a file in the app's own bundle; a path the bundle does not have is fetched as written. `.hdr` and `.exr` hold real light values; `.jpg`, `.png` and `.webp` are ordinary pictures. An `.hdr` or `.exr` may be 8192 by 4096 at most (that is already a quarter of a gigabyte once unpacked) and no larger than the device can draw; a larger one, or a file that is not what its header says, is not loaded: a warning says why, and the scene stays lit as it was.\n  - format: The kind of file, for an address whose ending does not say: 'hdr', 'exr' or 'image'. Left out, the ending decides (`.hdr`, `.exr`; anything else is taken for an ordinary picture).\n  - background: Show the panorama behind everything as well as lighting the scene with it (default false: the scene's `background` or `sky` is shown). Not with an orthographic camera, which has no view outward to show.\n  - rotation: Turn the panorama about the upright (y) axis, in radians (default 0): the lighting, the reflections and the background turn together, to put its sun where the scene wants it.\n  - blur: How blurred the background is, from 0 (sharp, the default) to 1 (a soft wash of its colours). The lighting is not changed by it.\n  - backgroundIntensity: How bright the background is shown, as a multiple (default 1). The lighting is not changed by it: that is `environmentIntensity`.\n- Scene3DEffects = { bloom?: boolean | { strength?: number; radius?: number; threshold?: number }; vignette?: number; grain?: number; depthOfField?: Scene3DDepthOfField | 'camera'; ambientOcclusion?: boolean | Scene3DAmbientOcclusion }\n  - bloom: Glow around bright things: true, or `{ strength, radius, threshold }` (defaults 0.45, 0.4 and 0.85: how strong the glow is, how far it spreads, and how bright a thing must be to glow).\n  - vignette: Darker corners, from 0 (none, the default) to 1.\n  - grain: Film noise, from 0 (none, the default) to 1.\n  - depthOfField: Depth of field: what is at one distance from the camera is sharp, and what is nearer or further is blurred, as through a lens. `{ focusOn, aperture, maxBlur }` keeps the object with that id sharp; `{ focus, aperture, maxBlur }` keeps a distance sharp, in scene units. With neither `focus` nor `focusOn`, there is no depth of field. `{ focusOn | focus, fstop, sensorHeight }` blurs as a lens of that f-number does. `\"camera\"` takes the focus from the camera of a model the scene is looking through (`camera={{ from }}`), as the file's record has it: what it is focused on, or how far (a distance of the model's, so as long in the scene as the model is drawn), and its f-number. A camera with no focus in the record, and a scene not looking through one, blurs nothing.\n  - ambientOcclusion: Ambient occlusion: the soft darkening where surfaces meet (a wheel on the ground, a bracket on a panel). True, or `{ radius, intensity }`. The costliest effect: the scene's solid things are drawn a second time and every pixel is then gone over twice, a few times what bloom costs.\n- Scene3DModelStateInfo = { objectId: string; parentId?: string }\n  - parentId: For a model that is a group's child: the id of that group.\n- Scene3DHit = { objectId: string; rootObjectId?: string; cursor?: string; button: number; locked: boolean; instanceId: number | null; distance: number | null; point: { x: number; y: number; z: number } | null; normal: { x: number; y: number; z: number } | null; screen: { x: number; y: number }; dragged: boolean }\n  What a click landed on. `objectId` is the empty string when the ray hit nothing, which a pointer-locked scene still reports so a game can fire into the sky. `instanceId` is set for an `instanced` object; `normal` is the face that was hit, in world space, which is what tells a builder where a new block goes.\n  - rootObjectId: The top-level object the hit belongs to: the group, for a group's child.\n  - button: The button pressed: 0 the main one, 1 the middle, 2 the other. -1 where no button was (a move, a hover).\n  - screen: Where the pointer is, in CSS pixels from the scene's top-left corner: the place to put a tooltip or a menu beside what was clicked. The middle of the scene while the pointer is locked.\n  - dragged: Whether the pointer moved between going down and coming up: true for the end of an orbit or a drag, false for a press that stayed put. Always false in a click, which a drag never is.\n- Scene3DAnimationInfo = { objectId: string; parentId?: string; clip: string; type: 'finished' | 'missing' }\n  A clip that ended, or one a model was asked for and does not have.\n  - parentId: For a model that is a group's child: the id of that group.\n- Scene3DCameraInfo = { position: { x: number; y: number; z: number }; target: { x: number; y: number; z: number }; size?: number }\n  Where the person left the camera, as `onCameraChange` reports it.\n  - position: Where the camera stands: give it back as `camera.position`.\n  - target: The point it orbits and looks at: give it back as `camera.lookAt`.\n  - size: For an orthographic camera: how much is in view from top to bottom, as zoomed. Give it back as `camera.size`.\n- Scene3DStats = { fps: number; drawCalls: number; triangles: number }\n  The scene's readout, as `onStats` reports it.\n  - fps: Frames drawn per second, over about the last second.\n  - drawCalls: Separate things the last frame drew: each object, each batch of instances, each pass of an effect.\n  - triangles: Triangles in the last frame.\n- ModelAppearance = { morphs?: Record<string, number>; morphSmoothingMs?: Record<string, number>; colors?: Record<string, string>; hiddenMeshes?: string[] }\n  Named, declarative appearance controls for imported assets.\n  - morphSmoothingMs: Optional per-target response time, 0–500 ms. Other morphs remain immediate.\n  - colors: A tint for each material, by the material's name (the \"loaded\" state of `onModelState` lists them). Any colour three.js reads: a name (`red`), three or six hex digits after a hash, `rgb(255, 0, 0)` or `hsl(0, 100%, 50%)`. It multiplies the material's own texture. One that cannot be read leaves the material as it was, with a console warning.\n- Scene3DShape = | 'box' | 'sphere' | 'cylinder' | 'capsule' | 'prism' | 'plane' | 'torus' | 'cone' | 'ring' | 'dodecahedron' | 'icosahedron' | 'octahedron'\n- ModelFormat = 'gltf' | 'obj' | 'fbx' | 'stl'\n- Scene3DPart = { rotation?: { x: number; y: number; z: number }; position?: { x: number; y: number; z: number }; scale?: number | { x: number; y: number; z: number }; visible?: boolean }\n  What is done to one named part of a model.\n  - rotation: A turn on top of the pose the file gives the part, about its own x, y and z, in radians, applied in that order.\n  - position: How far the part is moved from where the file puts it, in the units and directions of what it hangs from.\n  - scale: A multiple of the size the file gives the part: one number, or one for each of x, y and z.\n  - visible: Show or hide the part and everything that hangs from it. Left out, it is as the file and `appearance` have it.\n- Scene3DModelLights = { intensity?: number; castShadow?: boolean; shadowMapSize?: number; shadowCameraSize?: number; shadowBias?: number; shadowNormalBias?: number }\n  What an object says of its model's own lights.\n  - intensity: A multiple of each light's own strength (default 1). 1 / 683 turns a Blender export in its \"Standard\" units into plain numbers.\n  - castShadow: Whether the model's directional and spot lights cast shadows (default false; the scene's `shadows` must be on).\n  - shadowMapSize: The shadow map's resolution in pixels (default 1024 for a directional light, 512 for a spot).\n  - shadowCameraSize: A directional light's shadows cover a box this many units each way (default 15), kept about what the camera sees.\n  - shadowBias: As a scene light's `shadowBias` (default -0.0005 for a directional light, none for a spot).\n  - shadowNormalBias: As a scene light's `shadowNormalBias`, in scene units (default 0).\n- ParticleShape = 'square' | 'round' | 'soft'\n  How a particle is drawn.\n- Scene3DFollow = { target: string; distance?: number; height?: number; lookAhead?: number }\n  A camera that keeps behind an object, worked out on every frame the scene draws.\n  - target: The `id` of the object to follow: a top-level object, or a group's child.\n  - distance: How far behind the object the camera stands, in scene units (default 6).\n  - height: How far above the object's position the camera stands (default 3).\n  - lookAhead: How far in front of the object the camera looks (default 0: at the object itself).\n- EnvironmentFormat = 'hdr' | 'exr' | 'image'\n  The kind of file a panorama is: what reads it.\nEvents (write @name={…}; the prop is onName):\n- @ready — Three milestones, in order. `onReady`: the renderer exists and has drawn a frame — the world may still be empty. `onAssetsReady`: every model the scene opened with has settled, loaded or failed (a failure is reported through `onModelState`; a model withheld by the permission policy is not counted, since it is not loading), and so has the panorama of its `environment`, if it opened with one. `onFirstFrame`: the first frame drawn after that — the one a loading screen should wait for. Each fires once per mount.\n- @assetsReady\n- @firstFrame\n- @modelState(info: Scene3DModelStateInfo) — Each model's load as it happens, as `{ objectId, state, attempt }`: `pending` when a fetch starts, `loaded` or `error` (with `error`, the reason, naming a refused subresource when that is why) when it settles. `attempt` counts `reload`s of the same URL. `loaded` also says what is in the model: `clips`, `materials`, `meshes` and `morphs` (lists of names, for `animation.clip` and `appearance`), `clipLengths` (seconds, one for each of `clips`), `nodes` (the names of its nodes, for `parts`), `cameras` and `lights` (the names of the cameras and lights the file has, for `camera={{ from, name }}` and the object's `lights`), `size` and `center` (`{ x, y, z }`, as the file gives them) and, for a file exported with SoftN's Blender script, `film` (how long it is, its cuts from camera to camera, each camera's lens and focus, its exposure and its panorama). A model in a group reports its group as `parentId`.\n- @click(info: Scene3DHit) — A click that landed on an object (a press and release without a drag, left button). The handler is given the hit: `objectId`, `rootObjectId` (the group, for a group's child), `instanceId` (for an instanced object), `point` and `normal` (`{ x, y, z }` in the world), `distance`, `screen` (`{ x, y }` in CSS pixels within the scene), `button`, `dragged` and `locked`. With `pointerLock`, every press is reported here while the pointer is locked, with `objectId` empty when it hit nothing.\n- @miss(info: Scene3DHit) — A click that landed on nothing: the way to deselect by clicking away. Given the same record as `onClick`, with `objectId` empty and `screen` where the click was. Not sent for the end of a drag, nor while the pointer is locked.\n- @pointerDown(info: Scene3DHit) — A button went down on the scene; the hit is what it went down on (`objectId` empty for nothing).\n- @pointerMove(info: Scene3DHit) — The pointer moved with a button held: at most once a frame, with where it is by then and what is under it. `dragged` is true once it has moved more than a few pixels. The last place it moved to is always sent before `onPointerUp`.\n- @pointerUp(info: Scene3DHit) — The button came up. `dragged` tells the end of an orbit or a drag (true) from a press that stayed put (false).\n- @hover(info: Scene3DHit) — The pointer moved over the scene with no button held: at most once a frame, with where it is now and what is under it (`objectId` empty for nothing). To react only when the object changes, use `onHoverChange`.\n- @hoverChange(info: Scene3DHit) — What is under the pointer changed: to another object, to another copy of an instanced object, or to nothing (`objectId` empty), which is also sent when the pointer leaves the scene, and when the object under a pointer that has not moved is taken out of the scene. The event for a highlight or a tooltip: it is not sent while the pointer moves over one object.\n- @animation(info: Scene3DAnimationInfo) — A model's clip ended (`type: 'finished'`) or it has no clip of the name asked for (`'missing'`): `{ objectId, clip, type }`.\n- @cameraChange(info: Scene3DCameraInfo) — The person finished turning, zooming or panning the view with orbit controls, and the camera has come to rest. Given `{ position, target }`, both `{ x, y, z }` (and `size` for an orthographic camera): keep them, and give them back as `camera.position` and `camera.lookAt` (and `camera.size`) to show the same view again.\n- @stats(info: Scene3DStats) — A readout about once a second while the scene is drawn: `{ fps, drawCalls, triangles }`, the frames drawn per second and what the last frame took. For a counter while an app is being made, or for an app that lowers its own quality when it runs slowly. Nothing is counted unless this is bound.\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Scene3D>…</Scene3D>\nFrom the docs (threejs-games):\n```xml\n<logic>\n  // A film made in Blender and exported as one file. This page is its clock.\n  let time = 0          // seconds into the film\n  let length = 0        // how long it is: the file says, once it has loaded\n  let playing = false\n\n  // What the scene draws: the whole of Blender's scene, held at this second of its animation.\n  // Its own lamps light it and cast its shadows.\n  $: objects = [{\n    id: \"film\", type: \"model\", modelUrl: \"assets/film.glb\", castShadow: true, receiveShadow: true,\n    animation: { clip: \"*\", time: time },\n    lights: { castShadow: true, shadowCameraSize: 20 }\n  }]\n\n  // The scene says what it loaded. A file from SoftN's export script for Blender carries the\n  // film's record: how long it is, which camera from when, each camera's lens and focus.\n  function loaded(model) {\n    if (model.state === \"loaded\" && model.film) length = model.film.duration\n  }\n\n  // One frame of the screen: the film is that much further on.\n  function step(dt) {\n    time = Math.min(length, time + dt)\n    if (time >= length) playing = false\n  }\n\n  // Play and stop; at the end, from the start again.\n  function toggle() {\n    if (!playing && time >= length) time = 0\n    playing = !playing\n  }\n</logic>\n\n<App theme=\"dark\">\n  <Stack direction=\"vertical\" gap=\"md\" padding=\"lg\">\n    <Heading level={1}>First drive</Heading>\n    <div style=\"position: relative; height: 420px\">\n      <Scene3D fill shadows objects={objects} camera={{ from: \"film\" }} environment={{ url: \"assets/film.hdr\" }} effects={{ depthOfField: \"camera\", ambientOcclusion: true }} toneMapping=\"agx\" @modelState={loaded} />\n    </div>\n    <Stack direction=\"horizontal\" gap=\"md\">\n      <Button variant=\"primary\" disabled={length === 0} @click={toggle}>{playing ? \"Stop\" : \"Play\"}</Button>\n      <Text>{time.toFixed(1)} of {length.toFixed(1)} seconds</Text>\n    </Stack>\n  </Stack>\n  <Loop frame running={playing} @tick={step} />\n</App>\n```",
 "SceneAnchor": "## SceneAnchor — Page content pinned to an object or a place in a Scene3D (a name tag, a health bar, a card); written inside the Scene3D, it follows the object as it moves.\nTag: <SceneAnchor> (group: scene3d)\nPage content pinned to a place in a 3D scene: written inside `<Scene3D>`, it holds ordinary markup and is kept over the object it names (or over a fixed `position`) as the object and the camera move. The scene moves it with one CSS transform a frame; the page is not redrawn for it. It is hidden while its place is behind the camera or outside the view, and while its object is not in the scene. Outside a `<Scene3D>` it shows nothing.\nProps (? = optional):\n- object?: string — The `id` of the object this content is pinned to: one of the scene's `objects` or `staticObjects`, or a child of a group. The content goes where the object is drawn, frame by frame, a model and an object that `transition` is easing included. While no object has that id, the content is hidden.\n- position?: { x: number; y: number; z: number } — A fixed place in the scene to pin the content to, `{ x, y, z }`, used when `object` is not given.\n- offset?: { x?: number; y?: number; z?: number } — How far the pin is from the object's own position (or from `position`), `{ x, y, z }` in scene units along the scene's axes: `{ y: 1 }` is one unit above, however the object is turned.\n- place?: \"center\" | \"above\" | \"below\" | \"left\" | \"right\" — Where the content sits about the pin: 'center' (its middle on the pin, the default), 'above' (a name over a head), 'below', 'left' or 'right' (a card beside a part).\n- clickThrough?: boolean — Let the pointer through to the scene: for a label that is only read, so a click or an orbit that starts on it still reaches what is behind. Without it the content takes the pointer, as a button in it must.\n- children?: node — The content: ordinary markup, a label, a health bar, a card with buttons.\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <SceneAnchor>…</SceneAnchor>\nFrom the docs (threejs-games):\n```xml\n<logic>\n  // The parts of a small plant. Each is one record: what to draw, and what to say of it.\n  let parts = [\n    { id: \"pump\", name: \"Pump\", note: \"1450 rpm\", type: \"cylinder\", radius: 0.5, height: 1.2, color: \"#3b82f6\", position: { x: -2, y: 0.6, z: 0 } },\n    { id: \"valve\", name: \"Valve\", note: \"Open 40%\", type: \"torus\", radius: 0.5, color: \"#f59e0b\", position: { x: 0, y: 0.6, z: 0 }, animate: { rotateY: 0.01 } },\n    { id: \"tank\", name: \"Tank\", note: \"62% full\", type: \"capsule\", radius: 0.6, height: 2, color: \"#10b981\", position: { x: 2, y: 1, z: 0 } }\n  ]\n  // The ground is scenery, not a part: a click on it is a click on nothing.\n  let ground = { id: \"ground\", type: \"plane\", width: 12, height: 12, rotation: { x: -Math.PI / 2, y: 0, z: 0 }, color: \"#1f2937\", pickable: false }\n  // The lights: a soft one from everywhere, and a sun.\n  let lights = [\n    { type: \"ambient\", intensity: 0.6 },\n    { type: \"directional\", intensity: 1.2, position: { x: 4, y: 8, z: 5 } }\n  ]\n  let selectedId = \"\"\n\n  $: selected = parts.find(part => part.id === selectedId)\n\n  // What the scene draws: every part, the chosen one lit from within and a little larger, and the ground.\n  $: objects = parts.map(part => ({\n    ...part,\n    emissive: part.id === selectedId ? part.color : \"#000000\",\n    emissiveIntensity: part.id === selectedId ? 0.6 : 0,\n    scale: part.id === selectedId ? 1.15 : 1\n  })).concat([ground])\n\n  // A click on a part says which one.\n  function pick(hit) {\n    selectedId = hit.objectId\n  }\n\n  // A click on nothing, and Close, put the reading away.\n  function close() {\n    selectedId = \"\"\n  }\n</logic>\n\n<App theme=\"dark\">\n  <Stack direction=\"vertical\" gap=\"md\" padding=\"lg\">\n    <Heading level={1}>Plant overview</Heading>\n    <Text>Drag to look around. Click a part for its reading.</Text>\n    <div style=\"position: relative; height: 420px\">\n      <Scene3D fill orbitControls orbit={{ minDistance: 4, maxDistance: 14, maxPolar: 1.45 }} transition={250} objects={objects} lights={lights} camera={{ position: { x: 0, y: 3, z: 7 }, lookAt: { x: 0, y: 0.8, z: 0 } }} @click={pick} @miss={close}>\n        #if (selected)\n          <SceneAnchor object={selected.id} place=\"above\" offset={{ y: 0.8 }}>\n            <Card title={selected.name}>\n              <Stack direction=\"vertical\" gap=\"sm\">\n                <Text>{selected.note}</Text>\n                <Button variant=\"ghost\" size=\"sm\" @click={close}>Close</Button>\n              </Stack>\n            </Card>\n          </SceneAnchor>\n        #end\n      </Scene3D>\n    </div>\n  </Stack>\n</App>\n```",
 "Section": "## Section — A titled section of a page, with an optional action.\nTag: <Section> (group: essentials)\nProps (? = optional):\n- children?: node — Section content\n- title?: string — Section title\n- subtitle?: string — Section subtitle/description\n- action?: node — Action buttons (top-right)\n- padding?: 'none' | 'sm' | 'md' | 'lg' | 'xl' | string — Padding\n- gap?: 'none' | 'sm' | 'md' | 'lg' | 'xl' | string — Gap between children\n- background?: string — Background color\n- borderRadius?: string — Border radius\n- collapsible?: boolean — Collapsible\n- defaultCollapsed?: boolean — Default collapsed state\n- headingLevel?: 1 | 2 | 3 | 4 | 5 | 6 — Heading level of the title (default 2)\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Section>…</Section>",
 "SegmentedControl": "## SegmentedControl — Choose one of a few options shown side by side; @change and :bind give the value.\nTag: <SegmentedControl> (group: controls)\nProps (? = optional):\n- options?: Array<string | number | SegmentedOption> — The options: values, or { value, label?, disabled? }\n- value?: string | number — The chosen option's value\n- defaultValue?: string | number — Starting choice, when the app does not hold it\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- fullWidth?: boolean — Stretch to the width available, each option an equal share\n- disabled?: boolean — Whether the control is disabled\n- ariaLabel?: string — Accessible name for the group\nTypes the props use:\n- SegmentedOption = { value: string | number; label?: string; disabled?: boolean }\n  - value: What choosing the option gives\n  - label: What the option shows; its value when omitted\n  - disabled: Whether the option cannot be chosen\nEvents (write @name={…}; the prop is onName):\n- @change(value: string | number) — Called with the chosen option's value\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <SegmentedControl />\nFrom the docs (components):\n```xml\n<SegmentedControl :bind={view} options={[\"List\", \"Board\", \"Calendar\"]} />\n<NumberInput :bind={quantity} min={1} max={99} />\n<Rating :bind={score} max={5} />\n<Steps items={[\"Cart\", \"Shipping\", \"Payment\"]} :bind={step} />\n```",
 "Select": "## Select — A dropdown to choose one option.\nTag: <Select> (group: controls)\nProps (? = optional):\n- name?: string — Input name\n- value?: string | number | (string | number)[] — Current value: the chosen option's value, text or a number (a list of them for multi); 2 and \"2\" choose the same option\n- defaultValue?: string | number | (string | number)[] — Default value\n- options?: SelectOptions — Options (flat or grouped); an option is { value, label } or a bare string or number\n- placeholder?: string — Placeholder text\n- label?: string — Label text\n- disabled?: boolean — Whether the input is disabled\n- required?: boolean — Whether the input is required\n- searchable?: boolean — Enable search/filter\n- searchPlaceholder?: string — Search placeholder\n- multiple?: boolean — Enable multi-select\n- maxSelections?: number — Max selections for multi-select\n- clearable?: boolean — Show clear button\n- size?: \"sm\" | \"md\" | \"lg\" — Input size\n- fullWidth?: boolean — Full width\n- error?: boolean | string — Error state or error message\n- loading?: boolean — Loading state\n- noOptionsText?: string — No options text\n- createOptionText?: function — Create option text (for creatable select)\nTypes the props use:\n- SelectOptions = (SelectOption | SelectOptionGroup | string | number)[]\n  A list of options: { value, label }, a group of them, or a bare string or number, which is its own value and label (`[\"low\", \"high\"]`, `[1, 2, 3]`).\n- SelectOption = { value: string | number; label: string; disabled?: boolean; icon?: string; description?: string }\n  - value: What choosing the option hands back: text, or a number such as a record's id\n- SelectOptionGroup = { label: string; options: (SelectOption | string | number)[] }\n  - options: The group's options, each written as in the list itself: { value, label } or bare\nEvents (write @name={…}; the prop is onName):\n- @change(value: string | number | (string | number)[]) — Change handler: the chosen option's own value (a number for a numbered option), or the list of them for multi\n- @search(query: string) — Search handler (for async options)\n- @create(value: string) — Create handler\n- @focus — Focus handler\n- @blur — Blur handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Select />",
 "Sidebar": "## Sidebar — A side column, collapsible.\nTag: <Sidebar> (group: essentials)\nProps (? = optional):\n- children?: node — Sidebar content\n- width?: string — Width when expanded\n- collapsedWidth?: string — Width when collapsed\n- position?: \"left\" | \"right\" — Which side to show on\n- collapsible?: boolean — Whether sidebar is collapsible\n- collapsed?: boolean — Controlled collapsed state\n- defaultCollapsed?: boolean — Default collapsed state\n- background?: string — Background color\n- borderColor?: string — Border color\n- showToggle?: boolean — Show toggle button\n- mobileMenu?: boolean — On a phone (768 pixels wide and under) the sidebar is a menu button that opens it as a drawer. `false` leaves it hidden there, for an app that draws its own phone navigation; an app with a `softn-mobile-only` element or a menu button of its own is taken to, without being told.\n- menuLabel?: string — The name of the menu button, and of the drawer it opens, for a screen reader\nEvents (write @name={…}; the prop is onName):\n- @collapse(collapsed: boolean) — Callback when collapsed state changes\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Sidebar>…</Sidebar>",
 "Skeleton": "## Skeleton — A loading placeholder shaped like the content to come; shows its children once loading is false.\nTag: <Skeleton> (group: display)\nProps (? = optional):\n- variant?: \"text\" | \"circular\" | \"rectangular\" | \"rounded\" — Variant of skeleton\n- width?: string | number — Width (CSS value or number for pixels)\n- height?: string | number — Height (CSS value or number for pixels)\n- animation?: \"pulse\" | \"wave\" | \"none\" — Animation type\n- speed?: \"slow\" | \"normal\" | \"fast\" — Animation speed\n- lines?: number — Number of text lines (only for text variant)\n- lineSpacing?: string — Line spacing for multi-line text\n- borderRadius?: string | number — Border radius (overrides variant default)\n- baseColor?: string — Base color (supports CSS variables)\n- highlightColor?: string — Highlight color for shimmer (supports CSS variables)\n- children?: node — Children to show when loading is false\n- loading?: boolean — Whether content is still loading\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Skeleton>…</Skeleton>",
 "SkeletonCard": "## SkeletonCard — Loading placeholder for a card (helper; not a registered tag).\nNot registered as a tag: it cannot be used in markup.\nSkeletonCard - Preset for card loading\nProps: none of its own.\nChildren: none (configure it with props).\nEvery component also takes style and className.",
 "SkeletonCircle": "## SkeletonCircle — Loading placeholder for an avatar (helper; not a registered tag).\nNot registered as a tag: it cannot be used in markup.\nSkeletonCircle - Preset for circular avatars\nProps: none of its own.\nChildren: none (configure it with props).\nEvery component also takes style and className.",
 "SkeletonText": "## SkeletonText — Loading placeholder for lines of text (helper; not a registered tag).\nNot registered as a tag: it cannot be used in markup.\nSkeletonText - Preset for text loading\nProps: none of its own.\nChildren: none (configure it with props).\nEvery component also takes style and className.",
 "Slider": "## Slider — Choose a number in a range by dragging.\nTag: <Slider> (group: controls)\nProps (? = optional):\n- value?: number — Current value\n- defaultValue?: number — Default value (uncontrolled)\n- min?: number — Minimum value\n- max?: number — Maximum value\n- step?: number — Step increment\n- disabled?: boolean — Disable the slider\n- showTooltip?: boolean — Show value tooltip on hover/drag\n- tooltipAlwaysVisible?: boolean — Tooltip always visible\n- formatTooltip?: function — Format tooltip value\n- ariaLabel?: string — Accessible name for the slider\n- marks?: boolean | { value: number; label?: string }[] — Show marks at intervals\n- size?: \"sm\" | \"md\" | \"lg\" — Size variant\n- variant?: \"primary\" | \"secondary\" | \"success\" | \"warning\" | \"danger\" — Color variant\n- trackColor?: string — Track color\n- fillColor?: string — Fill color\n- thumbColor?: string — Thumb color\nEvents (write @name={…}; the prop is onName):\n- @change(value: number) — Change handler\n- @changeEnd(value: number) — Change end handler (on mouse up)\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Slider />\nFrom the docs (components):\n```xml\n<DescriptionList items={[{ label: \"Customer\", value: order.name }, { label: \"Paid\", value: order.paid }]} columns={2} />\n\n<Field label=\"Volume\" hint=\"Applies to every sound.\" error={volumeError}>\n  <Slider :bind={volume} />\n</Field>\n\n<ButtonGroup ariaLabel=\"Range\">\n  <Button @click={() => range = \"day\"}>Day</Button>\n  <Button @click={() => range = \"week\"}>Week</Button>\n</ButtonGroup>\n\n<CopyButton value={inviteLink} label=\"Copy invite\" />\n\n<Confirm open={asking} title=\"Delete this note?\" message=\"This cannot be undone.\"\n         confirmText=\"Delete\" variant=\"danger\"\n         @confirm={() => remove()} @cancel={() => asking = false} />\n\n<AvatarGroup max={3}>\n  #each (person in people) key={person.id}\n    <Avatar name={person.name} />\n  #end\n</AvatarGroup>\n```",
 "SmartCards": "## SmartCards — Cards generated from records, mapping fields to title, image, badges.\nTag: <SmartCards> (group: smart)\nProps (? = optional):\n- data: T[] — Data array to display\n- title?: string — Field to use as card title\n- subtitle?: string — Field to use as card subtitle\n- description?: string — Field to use as card description\n- image?: string — Field to use as card image/avatar\n- badges?: string — Comma-separated fields to show as badges\n- meta?: string — Comma-separated fields to show as metadata\n- columns?: number | { sm?: number; md?: number; lg?: number } — Number of columns\n- variant?: \"default\" | \"elevated\" | \"outline\" | \"compact\" — Card variant\n- searchable?: boolean — Enable search\n- selectable?: boolean — Enable selection\n- renderCard?: function — Custom render for card content\n- emptyMessage?: string — Empty state message\nEvents (write @name={…}; the prop is onName):\n- @select(item: T) — Click handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <SmartCards data={[]} />",
 "SmartForm": "## SmartForm — A form generated from field definitions.\nTag: <SmartForm> (group: smart)\nProps (? = optional):\n- fields?: string | Array<FieldConfig | string> — Field configurations - can be comma-separated string or array of FieldConfig\n- data?: Record<string, unknown> — Initial form data\n- defaults?: Record<string, unknown> — Values a new record starts with, for fields the form shows or not: `defaults={{ visits: 0, vip: false }}`. What `data` holds and a field's own `defaultValue` come first. Not applied when editing a record (`recordId`, or `mode=\"edit\"`).\n- submitText?: string — Submit button text\n- cancelText?: string — Cancel button text\n- showCancel?: boolean — Show cancel button\n- layout?: \"vertical\" | \"horizontal\" | \"inline\" — Layout style\n- columns?: number — Number of columns for grid layout\n- title?: string — Form title\n- description?: string — Form description\n- loading?: boolean — Loading state\n- disabled?: boolean — Disabled state\n- collection?: string — XDB collection name - enables automatic persistence\n- recordId?: string — Record ID for editing (used with collection)\n- mode?: \"create\" | \"edit\" — Mode: 'create' or 'edit' (auto-detected from recordId if not specified)\n- afterSave?: \"clear\" | \"keep\" — What a form that saves to a `collection` does once a new record is saved. `clear` (the default) starts it again, from `data` and the defaults, ready for the next record; `keep` leaves what was typed. Either way it says \"Saved\" for a moment. A record being edited keeps its values.\n- savedText?: string — What the form says once a record is saved\nTypes the props use:\n- FieldConfig = {\n    name: string — Field name (required)\n    type?: | 'text' | 'email' | 'password' | 'number' | 'date' | 'select' | 'checkbox' | 'textarea' | 'tel' | 'url' — Field type\n    label?: string — Field label (auto-generated from name if not provided)\n    placeholder?: string — Placeholder text\n    required?: boolean — Whether field is required\n    min?: number — Minimum value (for number) or length (for text)\n    max?: number — Maximum value (for number) or length (for text)\n    pattern?: string — Regex pattern for validation\n    options?: ({ value: string; label: string } | string)[] — Options for select field: { value, label }, or a bare string, which is its own value\n    defaultValue?: unknown — Default value\n    validate?: (value: unknown, formData: Record<string, unknown>) => string | null — Custom validation function\n    disabled?: boolean — Disabled state\n    helpText?: string — Help text below field\n  }\nEvents (write @name={…}; the prop is onName):\n- @submit(data: Record<string, unknown>) — Submit handler\n- @change(data: Record<string, unknown>) — Change handler\n- @cancel — Cancel handler\n- @saved(record: unknown) — Called after successful save to XDB\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <SmartForm />\nFrom the docs (forms-tables-dashboards):\n```xml\n<SmartForm\n  collection=\"clients\"\n  fields=\"name:text:required, email:email:required, phone:text\"\n  submitText=\"Add Client\"\n/>\n```",
 "SmartGrid": "## SmartGrid — A searchable, sortable table generated from records.\nTag: <SmartGrid> (group: smart)\nProps (? = optional):\n- data: T[] — Data array or collection name (for XDB)\n- columns?: string — Comma-separated column names, or auto-detect if not provided\n- columnLabels?: Record<string, string> — Display labels keyed by stable field name.\n- searchable?: boolean — Enable search (new: searchable, legacy: search)\n- search?: boolean\n- sortable?: boolean — Enable sorting (new: sortable, legacy: sort)\n- sort?: boolean\n- pageable?: boolean — Enable pagination (new: pageable, legacy: pagination)\n- pagination?: boolean\n- pageSize?: number — Items per page\n- editable?: boolean — Enable editing (new: editable, legacy: edit)\n- edit?: boolean\n- delete?: boolean — Enable delete\n- add?: boolean — Enable add new\n- selectTo?: string — Auto-assign selected row to variable (new DSL pattern)\n- renderColumn?: Record<string, (value: unknown, row: T) => React.ReactNode> — Custom column renderers\n- hideColumns?: string[] — Hide specific columns\n- rowKey?: string — Row key field\n- emptyMessage?: string — Empty state message\n- loading?: boolean — Loading state\n- export?: 'csv' | 'xlsx' | boolean — Export format\nEvents (write @name={…}; the prop is onName):\n- @select(row: T) — Row selection handler\n- @add(data: Partial<T>) — Add handler\n- @edit(row: T, data: Partial<T>) — Edit handler\n- @delete(row: T) — Delete handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <SmartGrid data={[]} />\nFrom the docs (forms-tables-dashboards):\n```xml\n<data><collection name=\"clients\" as=\"clients\" /></data>\n\n<SmartGrid\n  data={clients}\n  columns=\"name, email, phone, visits\"\n  searchable sortable pageable\n/>\n```",
 "SmartList": "## SmartList — A list generated from records, mapping fields to lines.\nTag: <SmartList> (group: smart)\nProps (? = optional):\n- data: T[] — Data array to display\n- primary?: string — Primary text field (main content)\n- secondary?: string — Secondary text field (subtitle)\n- tertiary?: string — Tertiary text field (timestamp, etc.)\n- badge?: string — Field for badge/status\n- avatar?: string — Field to use for avatar (name for initials, or image URL)\n- icon?: string — Field for left icon\n- dividers?: boolean — Show dividers between items\n- variant?: \"default\" | \"compact\" | \"card\" — Variant style\n- selectable?: boolean — Enable selection\n- maxItems?: number — Max items to show (for preview lists)\n- showViewAll?: boolean — Show \"View All\" link when truncated\n- emptyMessage?: string — Empty state message\nEvents (write @name={…}; the prop is onName):\n- @select(item: T) — Click handler\n- @viewAll — View all click handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <SmartList data={[]} />",
 "SmartStats": "## SmartStats — Stat tiles with trends.\nTag: <SmartStats> (group: smart)\nProps (? = optional):\n- stats?: string | StatItem[] — Stats as comma-separated \"label: value\" pairs or array of StatItem\n- icons?: string — Comma-separated icon names for each stat\n- trends?: string — Comma-separated trend values (e.g., \"+12%, -5%, +0%\")\n- layout?: \"grid\" | \"row\" | \"compact\" — Layout style\n- columns?: number | { sm?: number; md?: number; lg?: number } — Number of columns for grid layout\n- variant?: \"default\" | \"gradient\" | \"outline\" | \"minimal\" — Card variant\n- size?: \"sm\" | \"md\" | \"lg\" — Size\nTypes the props use:\n- StatItem = { label: string; value: number | string; icon?: string; trend?: string | number; trendDirection?: 'up' | 'down' | 'neutral'; color?: string; prefix?: string; suffix?: string }\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <SmartStats />",
 "SmartTimeline": "## SmartTimeline — A timeline of records.\nTag: <SmartTimeline> (group: smart)\nProps (? = optional):\n- data: T[] — Data array to display\n- title?: string — Field for event title/action\n- description?: string — Field for event description\n- time?: string — Field for timestamp\n- status?: string — Field for status/type (determines icon/color)\n- actor?: string — Field for user/actor\n- variant?: \"default\" | \"compact\" | \"card\" — Variant style\n- showLine?: boolean — Show connecting lines\n- maxItems?: number — Max items to show\n- emptyMessage?: string — Empty state message\nEvents (write @name={…}; the prop is onName):\n- @select(item: T) — Click handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <SmartTimeline data={[]} />",
 "SmartView": "## SmartView — Shows one record's fields as a card, list or grid.\nTag: <SmartView> (group: smart)\nProps (? = optional):\n- data: Record<string, unknown> | null | undefined — Data object to display\n- fields?: string — Comma-separated field names to display, or show all if not provided\n- layout?: \"card\" | \"list\" | \"inline\" | \"grid\" — Layout style\n- gridColumns?: number — Number of columns for grid layout\n- showLabels?: boolean — Show labels\n- labelPosition?: \"top\" | \"left\" | \"inline\" — Label position\n- title?: string — Title for the view\n- showEmpty?: boolean — Show empty values\n- formatters?: Record<string, (value: unknown) => React.ReactNode> — Custom formatters\n- hideFields?: string[] — Hide specific fields\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <SmartView data={data} />",
 "SortableList": "## SortableList — A list the person can reorder by dragging.\nTag: <SortableList> (group: animation)\nProps (? = optional):\n- items: unknown[] — Array of items to render\n- renderKey?: string — Field name to use as React key (defaults to index)\n- primary?: string — Field name for primary text display\n- secondary?: string — Field name for secondary/subtitle text display\n- direction?: \"vertical\" | \"horizontal\" — Layout direction\n- gap?: number — Gap between items in pixels\n- ariaLabel?: string — Accessible name for the list\nEvents (write @name={…}; the prop is onName):\n- @reorder(newItems: unknown[]) — Callback with the reordered items array\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <SortableList items={[]} />",
 "Spacer": "## Spacer — Empty space, fixed or flexible.\nTag: <Spacer> (group: essentials)\nProps (? = optional):\n- size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Fixed size (overrides flex)\n- flex?: number — Flex grow value\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Spacer />",
 "Spinner": "## Spinner — A loading indicator.\nTag: <Spinner> (group: essentials)\nProps (? = optional):\n- variant?: \"ring\" | \"dots\" | \"bars\" | \"pulse\" — Spinner variant\n- size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Spinner size\n- color?: 'primary' | 'secondary' | 'success' | 'warning' | 'danger' | 'white' | string — Spinner color\n- thickness?: number — Spinner thickness (for ring variant)\n- speed?: number — Speed in seconds\n- label?: string — Label for accessibility\n- glow?: boolean — Show glow effect\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Spinner />",
 "Split": "## Split — Two panes with a draggable divider.\nTag: <Split> (group: essentials)\nProps (? = optional):\n- children: [React.ReactNode, React.ReactNode] — First pane content\n- direction?: \"horizontal\" | \"vertical\" — Direction of the split\n- initialSize?: string | number — Initial size of the first pane (percentage or pixels)\n- minSize?: number — Minimum size of first pane in pixels\n- maxSize?: number — Maximum size of first pane in pixels\n- gutterSize?: number — Width of the gutter/divider\n- gutterColor?: string — Color of the gutter\n- ariaLabel?: string — Accessible name for the divider (default \"Resize panes\")\nEvents (write @name={…}; the prop is onName):\n- @resize(size: number) — Callback when size changes\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Split>…</Split>",
 "Sprite": "## Sprite — Draws and animates the frames of a sprite sheet at x, y: game characters. frames, loop and @end play a run once.\nTag: <Sprite> (group: animation)\nProps (? = optional):\n- src: string — URL of the sprite sheet image. A path with no scheme (`\"assets/hero.png\"`) names a file in the app's own bundle, so logic can name a sheet without `asset()`; a path the bundle does not have is loaded as written.\n- frameWidth?: number — Width of a single frame in pixels\n- frameHeight?: number — Height of a single frame in pixels\n- columns?: number — Number of columns in the sprite sheet (frames per row)\n- rows?: number — Number of rows in the sprite sheet (direction rows); `row` is kept within them\n- row?: number — Row index into the sheet. Which direction each row faces is the sheet's business, not this component's — the packs differ, and a stated convention here reads as a promise. Check the sheet.\n- colOffset?: number — Column offset for color variant (variantIndex × columns)\n- frames?: number[] — The frames to play, in order, instead of the whole row: `frames={[4, 5, 6]}`. A frame is counted along the sheet from the first frame of `row`, left to right and then down, so with `columns={8}` frame 9 is the second frame of the row below. A list of one frame holds that frame.\n- loop?: boolean — Whether the frames start again after the last (default true). With `loop={false}` they play once from the first, stay on the last, and `@end` is called: a jump, an explosion. It plays again when `frames` changes, or when `playing` is turned off and on.\n- playing?: boolean — Whether the animation is playing\n- fps?: number — Animation frames per second\n- scale?: number — Display scale multiplier\n- x?: number — Where the sprite's left edge is, in pixels from the left of its container (the nearest positioned element: give the playing field `position: relative`). Moved by a transform, which the browser does without laying the page out again.\n- y?: number — Where the sprite's top edge is, in pixels from the top of its container\n- flipX?: boolean — Mirror the sprite left to right, in place: a walk drawn facing right, shown facing left\n- zIndex?: number — CSS z-index\n- ariaLabel?: string — Accessible name; a clickable sprite without one is called \"Sprite\"\nEvents (write @name={…}; the prop is onName):\n- @click — Click handler; the sprite becomes a button, operable with Enter and Space\n- @end — Called when a `loop={false}` run reaches its last frame. Where the person has asked for reduced motion the frames are not played: the last is shown and this is called at once.\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Sprite src=\"src\" />",
 "Stack": "## Stack — Lays children out in a row or column with a gap: the everyday layout.\nTag: <Stack> (group: essentials)\nProps (? = optional):\n- direction?: \"horizontal\" | \"vertical\" — Direction of the stack\n- gap?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Gap between children\n- align?: \"start\" | \"center\" | \"end\" | \"stretch\" | \"baseline\" — Alignment of children on the cross axis\n- justify?: \"start\" | \"center\" | \"end\" | \"between\" | \"around\" | \"evenly\" — Justify content on the main axis\n- wrap?: boolean — Whether to wrap children\n- flex?: number | string — Flex value\n- padding?: 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | string — Padding\n- height?: string — Height\n- width?: string — Width\n- maxWidth?: string — Max width - useful for centering content\n- margin?: string — Margin - e.g., '0 auto' to center\n- paddingTop?: string — Padding top\n- mobileVertical?: boolean — Switch to vertical on mobile (< 768px)\n- mobileHorizontal?: boolean — Switch to horizontal on mobile\n- mobileReverse?: boolean — Reverse direction on mobile\n- children?: node — Children\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Stack>…</Stack>\nFrom the docs (machine-learning-torch):\n```xml\n<logic src=\"../logic/main.py\" />\n\n<App>\n  <Stack direction=\"vertical\" gap=\"md\" padding=\"lg\">\n    <Text>Loss: {loss}</Text>\n    <Button variant=\"primary\" @click={() => train(50)}>Train 50 steps</Button>\n  </Stack>\n</App>\n```",
 "Stat": "## Stat — One figure with its label and how it moved: a dashboard tile fed from state.\nTag: <Stat> (group: display)\nProps (? = optional):\n- label?: string — What the figure is\n- value?: string | number — The figure\n- prefix?: string — Text before the value, such as a currency sign\n- suffix?: string — Text after the value, such as a unit\n- change?: number | string — How far it moved: a number is shown as a percentage, text as written\n- changeLabel?: string — What the change is measured against, such as \"since last week\"\n- trend?: \"up\" | \"down\" | \"flat\" — Direction of the change (worked out from a numeric change when omitted)\n- positive?: \"up\" | \"down\" — Which direction is good news; the other is shown as a warning\n- helpText?: string — A line of explanation under the figure\n- icon?: node — Icon shown beside the label\n- variant?: \"plain\" | \"card\" | \"outlined\" — Appearance\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- align?: \"left\" | \"center\" | \"right\" — Alignment of the content\n- children?: node — Content under the figure, such as a sparkline\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Stat>…</Stat>",
 "Steps": "## Steps — Where someone is in a sequence: done, current and upcoming steps; with @change the steps are buttons.\nTag: <Steps> (group: navigation)\nProps (? = optional):\n- items?: Array<string | StepItem> — The steps, in order: names, or { key?, label, description?, disabled? }\n- current?: number | string — The step in progress: its position from zero, or its key\n- value?: number | string — The same as current, under the name `:bind` writes\n- orientation?: \"horizontal\" | \"vertical\" — Lay the steps out in a row or a column\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- status?: \"process\" | \"error\" — How the step in progress is shown\n- ariaLabel?: string — Accessible name for the list\nTypes the props use:\n- StepItem = { key?: string; label: string; description?: string; disabled?: boolean }\n  - key: What the step is called when chosen; its position is used when omitted\n  - label: The step's name\n  - description: A line under the name\n  - disabled: Whether the step cannot be chosen\nEvents (write @name={…}; the prop is onName):\n- @change(step: number | string) — Called with the chosen step's key, or its position when it has none\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Steps />\nFrom the docs (components):\n```xml\n<SegmentedControl :bind={view} options={[\"List\", \"Board\", \"Calendar\"]} />\n<NumberInput :bind={quantity} min={1} max={99} />\n<Rating :bind={score} max={5} />\n<Steps items={[\"Cart\", \"Shipping\", \"Payment\"]} :bind={step} />\n```",
 "Switch": "## Switch — An on/off toggle with a label; :bind={name} holds true or false.\nTag: <Switch> (group: controls)\nProps (? = optional):\n- name?: string — Input name\n- checked?: boolean — Whether checked\n- defaultChecked?: boolean — Default checked state\n- label?: string — Label text\n- description?: string — Description text below label\n- disabled?: boolean — Whether the input is disabled\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- onColor?: string — Color when on\n- offColor?: string — Color when off\nEvents (write @name={…}; the prop is onName):\n- @change(event) — Change handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Switch />",
 "Table": "## Table — A table from columns [{ key, header }] and data rows.\nTag: <Table> (group: data)\nProps (? = optional):\n- columns: Column<T>[] — Table columns\n- data: T[] — Table data\n- rowKey?: string | ((row: T, index: number) => string) — Row key field\n- variant?: \"default\" | \"striped\" | \"bordered\" — Table variant\n- size?: \"sm\" | \"md\" | \"lg\" — Table size\n- stickyHeader?: boolean — Whether header is sticky\n- mobileCards?: \"auto\" | \"always\" | \"never\" — On a phone (640 pixels wide and under), whether each row is drawn as a card: its first cell as the heading, the others beside their column's name. `auto` (the default) does so when the table is too wide for its box and would scroll sideways; `always` does so whatever its width; `never` leaves it a table that scrolls.\n- hoverable?: boolean — Whether rows are hoverable\n- sortColumn?: string — Current sort column\n- sortDirection?: \"asc\" | \"desc\" — Sort direction\n- emptyContent?: node — Empty state content\n- caption?: node — Visible caption naming the table\n- ariaLabel?: string — Accessible name for the table (default: the caption, else \"Data table\")\nTypes the props use:\n- Column = { key: string; header: string; width?: string | number; align?: 'left' | 'center' | 'right'; sortable?: boolean; render?: (value: unknown, row: T, index: number) => string }\n  - key: Column key (maps to data property)\n  - header: Column header\n  - width: Column width\n  - align: Text alignment\n  - sortable: Whether column is sortable\n  - render: Custom render function\nEvents (write @name={…}; the prop is onName):\n- @rowClick(row: T, index: number) — Row click handler\n- @sort(column: string, direction: 'asc' | 'desc') — Sort change handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Table columns={[]} data={[]} />",
 "Tabs": "## Tabs — Tabs from [{ key, label }]; @change receives the key.\nTag: <Tabs> (group: navigation)\nProps (? = optional):\n- tabs: Tab[] — Tab items\n- activeKey?: string — Active tab key\n- defaultActiveKey?: string — Default active tab key\n- variant?: \"default\" | \"pills\" | \"underline\" — Tabs variant\n- size?: \"sm\" | \"md\" | \"lg\" — Tabs size\n- fullWidth?: boolean — Full width tabs\n- ariaLabel?: string — Accessible name for the tab list\nTypes the props use:\n- Tab = { key: string; label: string; content?: string; disabled?: boolean; icon?: string }\n  - key: Unique tab key\n  - label: Tab label\n  - content: Tab content\n  - disabled: Whether tab is disabled\n  - icon: Icon\nEvents (write @name={…}; the prop is onName):\n- @change(key: string) — Tab change handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Tabs tabs={[]} />\nFrom the docs (ui-language):\n```xml\n<Button @click={() => adding = true}>New task</Button>\n<Modal :bind={adding} title=\"New task\">…</Modal>\n<Confirm :bind={asking} title=\"Delete this task?\" @confirm={() => remove(task)} />\n<Tabs :bind={tab} tabs={[{ key: \"open\", label: \"Open\" }, { key: \"done\", label: \"Done\" }]} />\n<Pagination :bind={page} totalPages={pages} />\n```",
 "Tag": "## Tag — A small label, optionally removable.\nTag: <Tag> (group: display)\nProps (? = optional):\n- variant?: \"default\" | \"primary\" | \"secondary\" | \"success\" | \"warning\" | \"danger\" | \"info\" — Tag variant\n- tagStyle?: \"solid\" | \"subtle\" | \"outline\" — Tag style\n- size?: \"sm\" | \"md\" | \"lg\" — Tag size\n- leftIcon?: node — Left icon/element\n- rightIcon?: node — Right icon/element\n- removable?: boolean — Show remove button\n- removeLabel?: string — Accessible name for the remove button (default: \"Remove\" plus the tag's text)\n- disabled?: boolean — Disabled state\n- rounded?: boolean — Border radius\n- children: node — Tag content\nEvents (write @name={…}; the prop is onName):\n- @remove — Remove handler\n- @click — Click handler\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Tag>…</Tag>",
 "TagGroup": "## TagGroup — A row of Tag tags that wraps.\nTag: <TagGroup> (group: display)\nProps (? = optional):\n- gap?: 'sm' | 'md' | 'lg' | string — Gap between tags\n- wrap?: boolean — Wrap tags\n- children: node — Tag children\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <TagGroup>…</TagGroup>",
 "Text": "## Text — A run of text: size, weight, colour, alignment, truncation.\nTag: <Text> (group: essentials)\nProps (? = optional):\n- content?: string — Text content\n- size?: \"xs\" | \"sm\" | \"md\" | \"lg\" | \"xl\" | \"2xl\" | \"3xl\" — Text size\n- weight?: \"light\" | \"normal\" | \"medium\" | \"semibold\" | \"bold\" — Font weight\n- variant?: \"default\" | \"muted\" | \"primary\" | \"secondary\" | \"success\" | \"warning\" | \"error\" — Text color variant\n- color?: string — Custom text color (overrides variant)\n- align?: \"left\" | \"center\" | \"right\" | \"justify\" — Text alignment\n- truncate?: boolean — Whether to truncate with ellipsis\n- lineClamp?: number — Maximum number of lines (with ellipsis)\n- lineHeight?: \"tight\" | \"normal\" | \"relaxed\" | \"loose\" — Line height\n- letterSpacing?: \"tight\" | \"normal\" | \"wide\" — Letter spacing\n- transform?: \"none\" | \"uppercase\" | \"lowercase\" | \"capitalize\" — Text transform\n- italic?: boolean — Font style\n- decoration?: \"none\" | \"underline\" | \"line-through\" — Text decoration\n- block?: boolean — Display as block element\n- flex?: number | string — Flex\n- children?: node — Children\n- as?: \"span\" | \"p\" | \"div\" | \"label\" — HTML element to render\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Text>…</Text>\nFrom the docs (ui-language):\n```xml\n<Button variant=\"primary\" size=\"md\">Save</Button>\n<Text>{message}</Text>\n<Text color={isDark ? \"white\" : \"black\"}>{message}</Text>\n```",
 "TextArea": "## TextArea — A multi-line text field.\nTag: <TextArea> (group: essentials)\nProps (? = optional):\n- name?: string — Input name\n- value?: string — Current value\n- defaultValue?: string — Default value\n- placeholder?: string — Placeholder text\n- label?: string — Label text\n- helperText?: string — Helper text below input\n- disabled?: boolean — Whether the input is disabled\n- readOnly?: boolean — Whether the input is read-only\n- required?: boolean — Whether the input is required\n- rows?: number — Number of visible rows\n- size?: \"sm\" | \"md\" | \"lg\" — Input size\n- fullWidth?: boolean — Full width\n- error?: boolean | string — Error state or error message\n- success?: boolean — Success state\n- resize?: \"none\" | \"vertical\" | \"horizontal\" | \"both\" — Allow resize\n- autoResize?: boolean — Auto-resize based on content\n- minHeight?: string — Minimum height for auto-resize\n- maxHeight?: string — Maximum height for auto-resize\n- maxLength?: number — Max length\n- showCharCount?: boolean — Show character count\nEvents (write @name={…}; the prop is onName):\n- @change(event) — Change handler\n- @focus(event) — Focus handler\n- @blur(event) — Blur handler\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <TextArea />",
 "TileMap": "## TileMap — Draws a tile map from a tileset: game levels.\nTag: <TileMap> (group: animation)\nProps (? = optional):\n- src?: string — URL of the tileset sprite sheet. A path with no scheme (`\"assets/tiles.png\"`) names a file in the app's own bundle, so logic can name a tileset without `asset()`; a path the bundle does not have is loaded as written.\n- tileSize?: number — Size of each tile in pixels (default 32)\n- tilesetColumns?: number — Number of tile columns in the tileset image\n- layers?: number[][][] — Array of tile layers (each is a 2D array of tile indices, -1 = empty)\n- mapWidth?: number — Map width in tiles; the longest row of the layers when not given\n- mapHeight?: number — Map height in tiles; the most rows a layer has when not given\n- scale?: number — Display scale multiplier\n- viewport?: boolean — Render only the clipped visible region, with a bounded screen-density backing store.\n- smooth?: boolean — Smooth high-resolution artwork when sampling down to the display density.\nEvents (write @name={…}; the prop is onName):\n- @visibleRangeChange(range:{x:number;y:number;width:number;height:number})\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <TileMap />",
 "Timeline": "## Timeline — Things that happened, in order, from a list in state: [{ title, description?, time?, variant? }].\nTag: <Timeline> (group: data)\nProps (? = optional):\n- items?: TimelineItem[] — The entries, in the order to show them: { title, description?, time?, variant?, key? }\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- timePosition?: \"inline\" | \"above\" — Where the time is shown\n- showLine?: boolean — Draw the line between markers\n- reverse?: boolean — Show the newest entry first by reversing the list\n- emptyText?: string — Text shown when there are no entries\n- ariaLabel?: string — Accessible name for the list\nTypes the props use:\n- TimelineItem = { key?: string; title: string; description?: string; time?: string; variant?: 'default' | 'primary' | 'success' | 'warning' | 'danger' | 'info' }\n  - key: Identifies the entry when the list changes\n  - title: What happened\n  - description: More about it\n  - time: When, as the text to show\n  - variant: Colour of the marker\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Timeline />",
 "Toast": "## Toast — A transient notification.\nTag: <Toast> (group: feedback)\nProps (? = optional):\n- variant?: \"info\" | \"success\" | \"warning\" | \"error\" — Toast variant\n- title?: string — Toast title\n- message?: string — Toast message\n- duration?: number — Duration in milliseconds (0 for persistent)\n- position?: \"top-right\" | \"top-left\" | \"top-center\" | \"bottom-right\" | \"bottom-left\" | \"bottom-center\" — Position on screen\n- showClose?: boolean — Whether to show close button\n- showProgress?: boolean — Whether to show progress bar\n- pauseOnHover?: boolean — Pause countdown on hover\n- isVisible?: boolean — Whether toast is visible\nEvents (write @name={…}; the prop is onName):\n- @close — Callback when toast is closed\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Toast />",
 "Tooltip": "## Tooltip — A hint shown on hover or focus.\nTag: <Tooltip> (group: feedback)\nProps (? = optional):\n- content: node — Tooltip content\n- title?: node — Title (rendered above content)\n- placement?: \"top\" | \"bottom\" | \"left\" | \"right\" | \"top-start\" | \"top-end\" | \"bottom-start\" | \"bottom-end\" — Placement\n- trigger?: 'hover' | 'click' | 'focus' | 'manual' | ('hover' | 'click' | 'focus')[] — Trigger mode. `hover` also opens on keyboard focus: content a mouse user can reach by pointing must be reachable from the keyboard too.\n- animation?: \"fade\" | \"scale\" | \"shift\" — Animation type\n- animationDuration?: number — Animation duration (ms)\n- showDelay?: number — Delay before showing (ms)\n- hideDelay?: number — Delay before hiding (ms)\n- disabled?: boolean — Whether tooltip is disabled\n- open?: boolean — Controlled visibility\n- defaultOpen?: boolean — Default visibility (uncontrolled)\n- arrow?: boolean — Arrow visibility\n- interactive?: boolean — Allow hover on tooltip (keeps it open)\n- maxWidth?: number | string — Max width before wrapping\n- offset?: number — Offset from trigger element\n- variant?: \"dark\" | \"light\" | \"primary\" | \"success\" | \"warning\" | \"danger\" — Color variant\n- size?: \"sm\" | \"md\" | \"lg\" — Size\n- tooltipClassName?: string — Additional CSS class for tooltip\n- tooltipStyle?: React.CSSProperties — Inline styles for tooltip\n- children: node — Trigger element\nEvents (write @name={…}; the prop is onName):\n- @openChange(open: boolean) — Visibility change handler\nChildren: accepts child content.\nEvery component also takes style and className.\nMinimal usage: <Tooltip content={content}>…</Tooltip>",
 "TooltipTrigger": "## TooltipTrigger — Wraps an element with a tooltip (helper; not a registered tag).\nNot registered as a tag: it cannot be used in markup.\nProps (? = optional):\n- content: node — Tooltip content\n- tooltipProps?: Omit<TooltipProps, 'content' | 'children'> — Other tooltip props\n- children: function — Children render function receives show/hide functions\nTypes the props use:\n- TooltipProps = {\n    content: string — Tooltip content\n    title?: string — Title (rendered above content)\n    placement?: | 'top' | 'bottom' | 'left' | 'right' | 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end' — Placement\n    trigger?: 'hover' | 'click' | 'focus' | 'manual' | ('hover' | 'click' | 'focus')[] — Trigger mode. `hover` also opens on keyboard focus: content a mouse user can reach by pointing must be reachable from the keyboard too.\n    animation?: 'fade' | 'scale' | 'shift' — Animation type\n    animationDuration?: number — Animation duration (ms)\n    showDelay?: number — Delay before showing (ms)\n    hideDelay?: number — Delay before hiding (ms)\n    disabled?: boolean — Whether tooltip is disabled\n    open?: boolean — Controlled visibility\n    defaultOpen?: boolean — Default visibility (uncontrolled)\n    arrow?: boolean — Arrow visibility\n    interactive?: boolean — Allow hover on tooltip (keeps it open)\n    maxWidth?: number | string — Max width before wrapping\n    offset?: number — Offset from trigger element\n    variant?: 'dark' | 'light' | 'primary' | 'success' | 'warning' | 'danger' — Color variant\n    size?: 'sm' | 'md' | 'lg' — Size\n    onOpenChange?: (open: boolean) => void — Visibility change handler\n    tooltipClassName?: string — Additional CSS class for tooltip\n    className?: string — Additional CSS class for container\n    tooltipStyle?: React.CSSProperties — Inline styles for tooltip\n    style?: React.CSSProperties — Inline styles for container\n    children: string — Trigger element\n  }\nChildren: accepts child content.\nEvery component also takes style and className.",
 "TreeView": "## TreeView — A tree of expandable nodes.\nTag: <TreeView> (group: data)\nProps (? = optional):\n- nodes: TreeNode[]\n- expandedIds?: Set<string>\n- selectedId?: string\n- defaultExpandAll?: boolean\n- showLines?: boolean\n- indent?: number\n- ariaLabel?: string — Accessible name for the tree\nTypes the props use:\n- TreeNode = { id: string; label: string; children?: TreeNode[]; icon?: string; disabled?: boolean; data?: unknown }\n  - data: Whatever the app attaches to the node; the tree only carries it.\nEvents (write @name={…}; the prop is onName):\n- @expand(id: string, expanded: boolean)\n- @select(id: string, node: TreeNode)\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <TreeView nodes={[]} />",
 "Typewriter": "## Typewriter — Types its text out character by character.\nTag: <Typewriter> (group: animation)\nProps (? = optional):\n- text: string | string[] — The text(s) to type out. When an array, cycles through each text.\n- speed?: number — Typing speed in milliseconds per character\n- deleteSpeed?: number — Deletion speed in milliseconds per character\n- pauseDuration?: number — Pause duration in milliseconds after finishing a text before deleting\n- loop?: boolean — Whether to loop through the texts (defaults to true for arrays)\n- cursor?: boolean — Whether to show the blinking cursor\n- cursorChar?: string — The character to use for the cursor\nEvents (write @name={…}; the prop is onName):\n- @complete — Callback invoked when all text has been typed (or at end of each cycle)\nChildren: none (configure it with props).\nEvery component also takes style and className.\nMinimal usage: <Typewriter text={text} />"
};
